// src/apps/agent-live-tail/agent-filter/tool.ts
var DEFAULT_DATASET = "otel-v1-apm-span-*";
var agentFilterRoute = defineRoute({
  id: "agent-filter",
  tool: {
    title: "Live tail by agent",
    description: "Snapshot of the 50 most recent spans where `attributes.gen_ai.agent.name` matches the given `agentName`. Pass `dataSourceId` (from `list_data_sources`) and `agentName`; optionally `dataset` (defaults to `otel-v1-apm-span-*`). Re-invoke to refresh \u2014 there is no streaming.",
    inputSchema: inputSchema21
  },
  propsSchema: propsSchema21,
  view: AgentFilterView,
  handler: async ({ dataSourceId, dataset, agentName }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET;
    const safeAgent = agentName.trim().replace(/"/g, '\\"');
    const query = `source = ${ds} | where attributes.gen_ai.agent.name = "${safeAgent}" | sort - startTime | head 50`;
    ctx.logger.log("[agent-live-tail.agent-filter] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result).map((row) => ({
        spanId: row.getString("spanId"),
        traceId: row.getString("traceId"),
        name: row.getString("name"),
        startTime: row.getString("startTime"),
        durationInNanos: row.getNumber("durationInNanos"),
        agentName: row.getString("attributes.gen_ai.agent.name") || agentName,
        serviceName: row.getString("serviceName"),
        statusCode: row.getNumber("statusCode")
      }));
      const props = {
        dataset: ds,
        agentName,
        query,
        fetchedAt: Date.now(),
        rows
      };
      return {
        props,
        text: rows.length === 0 ? `No recent spans for agent "${agentName}" in ${ds}.` : `Loaded ${rows.length} recent span(s) for agent "${agentName}".`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-live-tail.agent-filter] failed: " + msg);
      const props = {
        dataset: ds,
        agentName,
        query,
        fetchedAt: Date.now(),
        rows: [],
        error: msg
      };
      return {
        props,
        text: "Failed to live tail by agent: " + msg,
        isError: true
      };
    }
  }
});

