// src/apps/agent-live-tail/span-search/tool.ts
var DEFAULT_DATASET2 = "otel-v1-apm-span-*";
function sanitize(q2) {
  return q2.replace(/[^A-Za-z0-9._\-/ ]/g, "").trim();
}
var spanSearchRoute = defineRoute({
  id: "span-search",
  tool: {
    title: "Search spans",
    description: "Search the most recent spans by free-form text against `name` and `attributes.gen_ai.tool.name` via PPL `like(...)`. Pass `dataSourceId` (from `list_data_sources`) and `query`; optionally `dataset` (defaults to `otel-v1-apm-span-*`). The query is sanitized \u2014 non-alphanumeric / non-`._-/ ` characters are stripped.",
    inputSchema: inputSchema24
  },
  propsSchema: propsSchema24,
  view: SpanSearchView,
  handler: async ({ dataSourceId, dataset, query }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET2;
    const safe = sanitize(query);
    const pattern = `%${safe}%`;
    const ppl = `source = ${ds} | where like(name, "${pattern}") or like(attributes.gen_ai.tool.name, "${pattern}") | sort - startTime | head 50`;
    ctx.logger.log("[agent-live-tail.span-search] PPL: " + ppl);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, ppl, ds);
      const rows = pplRows(result).map((row) => ({
        spanId: row.getString("spanId"),
        traceId: row.getString("traceId"),
        name: row.getString("name"),
        serviceName: row.getString("serviceName"),
        toolName: row.getString("attributes.gen_ai.tool.name"),
        durationInNanos: row.getNumber("durationInNanos"),
        startTime: row.getString("startTime"),
        statusCode: row.getNumber("statusCode")
      }));
      const props = {
        dataset: ds,
        searchQuery: safe,
        pplQuery: ppl,
        fetchedAt: Date.now(),
        rows
      };
      return {
        props,
        text: rows.length === 0 ? `No spans match "${safe}".` : `Loaded ${rows.length} matching span(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-live-tail.span-search] failed: " + msg);
      const props = {
        dataset: ds,
        searchQuery: safe,
        pplQuery: ppl,
        fetchedAt: Date.now(),
        rows: [],
        error: msg
      };
      return { props, text: "Failed to search spans: " + msg, isError: true };
    }
  }
});

