var DEFAULT_DATASET3 = "otel-v1-apm-span-*";
var viewRoute = defineRoute({
  id: "view",
  tool: {
    title: "Agent live tail",
    description: "Snapshot of the 20 most recent root spans. Pass `dataSourceId` (from `list_data_sources`) and optionally `dataset` (defaults to `otel-v1-apm-span-*`). Re-invoke this tool to refresh \u2014 there is no real streaming.",
    inputSchema: inputSchema25
  },
  propsSchema: propsSchema25,
  view: ViewView,
  handler: async ({ dataSourceId, dataset }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET3;
    const query = `source = ${ds} | where parentSpanId = "" | sort - startTime | head 20`;
    ctx.logger.log("[agent-live-tail.view] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const traces = pplRows(result).map((row) => ({
        traceId: row.getString("traceId"),
        name: row.getString("name"),
        startTime: row.getString("startTime"),
        durationInNanos: row.getNumber("durationInNanos")
      }));
      const props = { dataset: ds, fetchedAt: Date.now(), traces };
      return {
        props,
        text: traces.length === 0 ? `No traces in ${ds} yet.` : `Loaded ${traces.length} recent root span(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-live-tail.view] failed: " + msg);
      const props = { dataset: ds, fetchedAt: Date.now(), traces: [], error: msg };
      return { props, text: "Failed to live tail traces: " + msg, isError: true };
    }
  }
});

