// src/apps/agent-traces/conversation-groups/tool.ts
var DEFAULT_DATASET4 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT2 = 50;
var CONV_FIELD = "attributes.gen_ai.conversation.id";
var conversationGroupsRoute = defineRoute({
  id: "conversation-groups",
  tool: {
    title: "Agent conversation groups",
    description: "Group agent traces by `attributes.gen_ai.conversation.id` and return per-conversation trace count, span count, total tokens, and first / last seen timestamps. Pass `dataSourceId` (from `list_data_sources`); optional `dataset` (default `otel-v1-apm-span-*` \u2014 discover via `list_index_patterns`) and `limit` (default 50).",
    inputSchema: inputSchema31
  },
  propsSchema: propsSchema31,
  view: ConversationGroupsView,
  handler: async ({ dataSourceId, dataset, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET4;
    const lim = limit ?? DEFAULT_LIMIT2;
    const query = `source = ${ds} | where \`${CONV_FIELD}\` != "" | stats count() as spans, count_distinct(traceId) as traces, sum(\`attributes.gen_ai.usage.input_tokens\`) as inTok, sum(\`attributes.gen_ai.usage.output_tokens\`) as outTok, min(startTime) as firstSeen, max(startTime) as lastSeen by \`${CONV_FIELD}\` | sort - lastSeen | head ${lim}`;
    ctx.logger.log("[agent-traces.conversation-groups] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const groups = pplRows(result).map((r8) => {
        const inputTokens = r8.getNumber("inTok");
        const outputTokens = r8.getNumber("outTok");
        return {
          conversationId: r8.getString(CONV_FIELD) || "(unset)",
          traces: r8.getNumber("traces"),
          spans: r8.getNumber("spans"),
          inputTokens,
          outputTokens,
          totalTokens: inputTokens + outputTokens,
          firstSeen: r8.getString("firstSeen"),
          lastSeen: r8.getString("lastSeen")
        };
      });
      const props = { ...baseProps, groups };
      return {
        props,
        text: groups.length === 0 ? `No conversation groups found in ${ds}.` : `Loaded ${groups.length} conversation group(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error(
        "[agent-traces.conversation-groups] PPL failed: " + msg
      );
      const props = {
        ...baseProps,
        groups: [],
        error: msg
      };
      return {
        props,
        text: "Failed to load conversation groups: " + msg,
        isError: true
      };
    }
  }
});

