var DEFAULT_LIMIT3 = 500;
var dagRoute = defineRoute({
  id: "dag",
  tool: {
    title: "Agent trace DAG",
    description: "DAG view of one agent trace as nodes-and-edges. Supports CSS-transform zoom (0.1x\u20132x), fit-to-screen, minimap toggle, and ERR badges on errored nodes (statusCode=2). Pass `dataSourceId`, `dataset` (e.g. `otel-v1-apm-span-*`), and `traceId`; optionally `limit` (default 500).",
    inputSchema: inputSchema32
  },
  propsSchema: propsSchema32,
  view: DagView,
  handler: async ({ dataSourceId, traceId, dataset, limit }, ctx) => {
    const ds = dataset.trim();
    const lim = limit ?? DEFAULT_LIMIT3;
    const safeId = traceId.replace(/"/g, '\\"');
    const query = `source = ${ds} | where traceId = "${safeId}" | head ${lim}`;
    ctx.logger.log("[agent-traces.dag] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const { spans, rangeStartNanos, rangeEndNanos } = transformPplToSpans(
        result,
        traceId
      );
      const props = {
        traceId,
        dataset: ds,
        spans,
        rangeStartNanos,
        rangeEndNanos
      };
      return {
        props,
        text: spans.length === 0 ? `No spans found for traceId=${traceId} in ${ds}.` : `Loaded DAG with ${spans.length} span(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-traces.dag] failed: " + msg);
      const props = {
        traceId,
        dataset: ds,
        spans: [],
        rangeStartNanos: 0,
        rangeEndNanos: 0,
        error: msg
      };
      return { props, text: "Failed to load DAG: " + msg, isError: true };
    }
  }
});

