var exceptionEventsRoute = defineRoute({
  id: "exception-events",
  tool: {
    title: "Exception events",
    description: "List span events of name `exception` from agent spans, rendered as stacktrace cards. Pass `dataSourceId`, `dataset` (e.g. `otel-v1-apm-span-*`); optionally `traceId` to scope to one trace.",
    inputSchema: inputSchema33
  },
  propsSchema: propsSchema33,
  view: ExceptionEventsView,
  handler: async ({ dataSourceId, traceId, dataset }, ctx) => {
    const ds = dataset.trim();
    const filters = [];
    if (traceId && traceId.trim()) {
      const safe = traceId.trim().replace(/"/g, '\\"');
      filters.push(`where traceId = "${safe}"`);
    }
    filters.push(`where attributes.gen_ai.system != ""`);
    const filterChain = filters.join(" | ");
    const query = `source = ${ds} | ${filterChain} | sort - startTime | head 500`;
    ctx.logger.log("[agent-traces.exception-events] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const exceptions = [];
      for (const row of pplRows(result)) {
        const events = row.get("events");
        const found = extractExceptions(events);
        if (found.length === 0) continue;
        for (const f8 of found) {
          exceptions.push({
            spanId: row.getString("spanId"),
            traceId: row.getString("traceId"),
            spanName: row.getString("name"),
            serviceName: row.getString("serviceName"),
            exceptionType: f8.type,
            exceptionMessage: f8.message,
            exceptionStacktrace: f8.stack,
            startTime: row.getString("startTime")
          });
        }
      }
      const props = {
        traceId,
        dataset: ds,
        query,
        exceptions
      };
      return {
        props,
        text: exceptions.length === 0 ? `No exception events found.` : `Loaded ${exceptions.length} exception event(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-traces.exception-events] failed: " + msg);
      const props = {
        traceId,
        dataset: ds,
        query,
        exceptions: [],
        error: msg
      };
      return {
        props,
        text: "Failed to load exception events: " + msg,
        isError: true
      };
    }
  }
});

