var DEFAULT_DATASET5 = "otel-v1-apm-span-*";
function pickAgentName(row) {
  const direct = row.getString("attributes.gen_ai.agent.name") || row.getString("gen_ai.agent.name");
  if (direct) return direct;
  const attrs = row.get("attributes");
  if (attrs && typeof attrs === "object") {
    const inner = attrs["gen_ai.agent.name"];
    if (typeof inner === "string" && inner) return inner;
    const gen = attrs["gen_ai"];
    if (gen && typeof gen === "object") {
      const agent = gen["agent"];
      if (agent && typeof agent === "object") {
        const name = agent["name"];
        if (typeof name === "string" && name) return name;
      }
    }
  }
  return "\u2014";
}
var listRoute5 = defineRoute({
  id: "list",
  tool: {
    title: "List agent traces",
    description: "List recent GenAI agent traces (root spans where `attributes.gen_ai.system` is set). Pass `dataSourceId` (from `list_data_sources`) and optionally `dataset` (defaults to `otel-v1-apm-span-*`).",
    inputSchema: inputSchema36
  },
  propsSchema: propsSchema36,
  view: ListView5,
  handler: async ({ dataSourceId, dataset }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET5;
    const query = `source = ${ds} | where parentSpanId = "" | where attributes.gen_ai.system != "" | sort - startTime | head 50`;
    ctx.logger.log("[agent-traces.list] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const traces = pplRows(result).map((row) => ({
        traceId: row.getString("traceId"),
        name: row.getString("name"),
        durationInNanos: row.getNumber("durationInNanos"),
        startTime: row.getString("startTime"),
        agentName: pickAgentName(row)
      }));
      const props = { dataset: ds, traces };
      return {
        props,
        text: traces.length === 0 ? `No agent traces found in ${ds}.` : `Loaded ${traces.length} agent trace(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-traces.list] failed: " + msg);
      const props = { dataset: ds, traces: [], error: msg };
      return { props, text: "Failed to list agent traces: " + msg, isError: true };
    }
  }
});

