// src/apps/agent-traces/metrics/tool.ts
var DEFAULT_DATASET6 = "otel-v1-apm-span-*";
var metricsRoute = defineRoute({
  id: "metrics",
  tool: {
    title: "Agent trace metrics",
    description: "Aggregate KPI snapshot for the gen_ai-instrumented span set: Total Traces / Total Spans / Total Tokens / P50 / P99 duration. Pass `dataSourceId` (from `list_data_sources`); optionally `dataset` (defaults to `otel-v1-apm-span-*`) and `since` (ISO8601 lower bound).",
    inputSchema: inputSchema37
  },
  propsSchema: propsSchema37,
  view: MetricsView,
  handler: async ({ dataSourceId, dataset, since }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET6;
    const filters = [`where attributes.gen_ai.system != ""`];
    if (since && since.trim()) {
      const safe = since.trim().replace(/"/g, '\\"');
      filters.push(`where startTime >= "${safe}"`);
    }
    const filterChain = filters.join(" | ");
    const query = `source = ${ds} | ${filterChain} | stats count() as totalSpans, dc(traceId) as totalTraces, sum(attributes.gen_ai.usage.total_tokens) as totalTokens, percentile(durationInNanos, 50) as p50, percentile(durationInNanos, 99) as p99`;
    ctx.logger.log("[agent-traces.metrics] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      totalTraces: 0,
      totalSpans: 0,
      totalTokens: 0,
      p50DurationNanos: 0,
      p99DurationNanos: 0
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result);
      const r8 = rows[0];
      const props = r8 ? {
        ...baseProps,
        totalSpans: r8.getNumber("totalSpans"),
        totalTraces: r8.getNumber("totalTraces"),
        totalTokens: r8.getNumber("totalTokens"),
        p50DurationNanos: r8.getNumber("p50"),
        p99DurationNanos: r8.getNumber("p99")
      } : baseProps;
      return { props, text: `Loaded agent trace KPIs from ${ds}.` };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-traces.metrics] failed: " + msg);
      const props = { ...baseProps, error: msg };
      return { props, text: "Failed to compute metrics: " + msg, isError: true };
    }
  }
});

