var opDurationRoute = defineRoute({
  id: "op-duration",
  tool: {
    title: "Operation duration percentiles",
    description: "Compute P50 / P95 / P99 of `durationInNanos` grouped by `gen_ai.operation.name` (when `groupBy='operation'`) or `gen_ai.request.model` (when `groupBy='model'`). Pass `dataSourceId`, `dataset` (e.g. `otel-v1-apm-span-*`), and `groupBy`.",
    inputSchema: inputSchema38
  },
  propsSchema: propsSchema38,
  view: OpDurationView,
  handler: async ({ dataSourceId, dataset, groupBy: groupBy2 }, ctx) => {
    const ds = dataset.trim();
    const field = groupBy2 === "model" ? "attributes.gen_ai.request.model" : "attributes.gen_ai.operation.name";
    const query = `source = ${ds} | where attributes.gen_ai.system != "" | stats count() as cnt, percentile(durationInNanos, 50) as p50, percentile(durationInNanos, 95) as p95, percentile(durationInNanos, 99) as p99 by ${field} | sort - p99 | head 50`;
    ctx.logger.log("[agent-traces.op-duration] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result).map((row) => ({
        group: row.getString(field) || "(unset)",
        count: row.getNumber("cnt"),
        p50: row.getNumber("p50"),
        p95: row.getNumber("p95"),
        p99: row.getNumber("p99")
      }));
      const props = {
        dataset: ds,
        groupBy: groupBy2,
        query,
        rows
      };
      return {
        props,
        text: rows.length === 0 ? `No groups found.` : `Loaded ${rows.length} group(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-traces.op-duration] failed: " + msg);
      const props = {
        dataset: ds,
        groupBy: groupBy2,
        query,
        rows: [],
        error: msg
      };
      return {
        props,
        text: "Failed to compute op duration: " + msg,
        isError: true
      };
    }
  }
});

