// src/apps/agent-traces/tree/tool.ts
var DEFAULT_LIMIT7 = 500;
var treeRoute = defineRoute({
  id: "tree",
  tool: {
    title: "Agent trace tree",
    description: "Tree view of one agent trace with `SpanCategoryBadge` colors per gen_ai operation. Pass `dataSourceId`, `dataset` (e.g. `otel-v1-apm-span-*`), and `traceId`; optionally `limit` (default 500).",
    inputSchema: inputSchema43
  },
  propsSchema: propsSchema43,
  view: TreeView,
  handler: async ({ dataSourceId, traceId, dataset, limit }, ctx) => {
    const ds = dataset.trim();
    const lim = limit ?? DEFAULT_LIMIT7;
    const safeId = traceId.replace(/"/g, '\\"');
    const query = `source = ${ds} | where traceId = "${safeId}" | head ${lim}`;
    ctx.logger.log("[agent-traces.tree] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const { spans, rangeStartNanos, rangeEndNanos } = transformPplToSpans(
        result,
        traceId
      );
      const props = {
        traceId,
        dataset: ds,
        spans,
        rangeStartNanos,
        rangeEndNanos
      };
      return {
        props,
        text: spans.length === 0 ? `No spans found for traceId=${traceId} in ${ds}.` : `Loaded ${spans.length} span(s) for trace ${traceId}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[agent-traces.tree] failed: " + msg);
      const props = {
        traceId,
        dataset: ds,
        spans: [],
        rangeStartNanos: 0,
        rangeEndNanos: 0,
        error: msg
      };
      return { props, text: "Failed to load tree: " + msg, isError: true };
    }
  }
});

