// src/apps/alerts-dashboard/summary/tool.ts
var DATASET = ".opensearch-alerting-alert-history-*";
var summaryRoute2 = defineRoute({
  id: "summary",
  tool: {
    title: "Alert volume summary",
    description: "Aggregate alert volume by severity over a time range. Pass `dataSourceId` (from `list_data_sources`) and optional `timeRange` (1h, 24h, 7d, 30d; default 24h). Reads from `.opensearch-alerting-alert-history-*` via PPL.",
    inputSchema: inputSchema44
  },
  propsSchema: propsSchema44,
  view: SummaryView2,
  handler: async ({ dataSourceId, timeRange }, ctx) => {
    const range2 = timeRange ?? "24h";
    const safeRange = range2.replace(/"/g, '\\"');
    const query = `source = ${DATASET} | where start_time > "now-${safeRange}" | stats count() as count by severity`;
    ctx.logger.log("[alerts-dashboard.summary] PPL: " + query);
    const baseProps = {
      dataset: DATASET,
      query,
      timeRange: range2
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET);
      const bySeverity = pplRows(result).map((row) => ({
        severity: row.getString("severity") || "unknown",
        count: row.getNumber("count")
      })).sort((a7, b7) => a7.severity.localeCompare(b7.severity));
      const total = bySeverity.reduce((s2, b7) => s2 + b7.count, 0);
      const props = { ...baseProps, bySeverity, total };
      return {
        props,
        text: total === 0 ? `No alerts in the last ${range2}.` : `${total} alert(s) in the last ${range2}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[alerts-dashboard.summary] PPL failed: " + msg);
      const props = {
        ...baseProps,
        bySeverity: [],
        total: 0,
        error: msg
      };
      return {
        props,
        text: "Failed to aggregate alerts: " + msg,
        isError: true
      };
    }
  }
});

