var DATASET2 = ".opensearch-alerting-alert-history-*";
var DEFAULT_LIMIT8 = 20;
var topFiringRoute = defineRoute({
  id: "top-firing",
  tool: {
    title: "Top firing monitors",
    description: "Find the noisiest OpenSearch alerting monitors by number of firings. Pass `dataSourceId` (from `list_data_sources`) and optional `limit` (default 20). Reads `.opensearch-alerting-alert-history-*` via PPL `stats count() by monitor_name`.",
    inputSchema: inputSchema45
  },
  propsSchema: propsSchema45,
  view: TopFiringView,
  handler: async ({ dataSourceId, limit }, ctx) => {
    const lim = limit ?? DEFAULT_LIMIT8;
    const query = `source = ${DATASET2} | stats count() as firings by monitor_name | sort - firings | head ${lim}`;
    ctx.logger.log("[alerts-dashboard.top-firing] PPL: " + query);
    const baseProps = {
      dataset: DATASET2,
      query,
      limit: lim
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET2);
      const monitors = pplRows(result).map((row) => ({
        monitorName: row.getString("monitor_name") || "(unnamed)",
        firings: row.getNumber("firings")
      }));
      const props = { ...baseProps, monitors };
      return {
        props,
        text: monitors.length === 0 ? "No firing history found." : `Top ${monitors.length} firing monitor(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[alerts-dashboard.top-firing] PPL failed: " + msg);
      const props = {
        ...baseProps,
        monitors: [],
        error: msg
      };
      return {
        props,
        text: "Failed to compute top firing: " + msg,
        isError: true
      };
    }
  }
});

