// src/apps/alerts-feed/detail/tool.ts
var DATASET3 = ".opensearch-alerting-alert-history-*";
var detailRoute = defineRoute({
  id: "detail",
  tool: {
    title: "Open one alert",
    description: "Open a single OpenSearch alert by id and read its monitor, severity, last firing time, condition message, and any runbook link. Pass `dataSourceId` (from `list_data_sources`) and `alertId` (the `alert_id` / `id` returned by `alerts-feed_list`). Reads from `.opensearch-alerting-alert-history-*` via PPL.",
    inputSchema: inputSchema48
  },
  propsSchema: propsSchema48,
  view: DetailView,
  handler: async ({ dataSourceId, alertId }, ctx) => {
    const safeId = alertId.replace(/"/g, '\\"');
    const query = `source = ${DATASET3} | where id = "${safeId}" or alert_id = "${safeId}" | head 1`;
    ctx.logger.log("[alerts-feed.detail] PPL: " + query);
    const baseProps = {
      dataset: DATASET3,
      query,
      alertId
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET3);
      const rows = pplRows(result);
      if (rows.length === 0) {
        const props2 = { ...baseProps, alert: null };
        return {
          props: props2,
          text: `No alert found with id "${alertId}" in ${DATASET3}.`
        };
      }
      const r8 = rows[0];
      const alert = {
        id: r8.getString("alert_id") || r8.getString("id") || alertId,
        monitorId: r8.getString("monitor_id"),
        monitorName: r8.getString("monitor_name"),
        triggerName: r8.getString("trigger_name"),
        severity: r8.getString("severity"),
        state: r8.getString("state"),
        startTime: r8.getString("start_time"),
        lastNotificationTime: r8.getString("last_notification_time"),
        message: r8.getString("alert_info") || r8.getString("message") || r8.getString("trigger.message_template"),
        runbookUrl: r8.getString("runbook_url") || r8.getString("trigger.runbook_url") || r8.getString("monitor.runbook_url"),
        errorMessage: r8.getString("error_message")
      };
      const props = { ...baseProps, alert };
      return {
        props,
        text: `Loaded alert ${alert.id} (monitor "${alert.monitorName || "\u2014"}").`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[alerts-feed.detail] PPL failed: " + msg);
      const props = { ...baseProps, alert: null, error: msg };
      return {
        props,
        text: "Failed to load alert: " + msg,
        isError: true
      };
    }
  }
});

