// src/apps/alerts-feed/filter/tool.ts
var DATASET4 = ".opensearch-alerting-alert-history-*";
var DEFAULT_LIMIT9 = 200;
function quote(v3) {
  return v3.replace(/"/g, '\\"');
}
var filterRoute = defineRoute({
  id: "filter",
  tool: {
    title: "Filter alerts",
    description: "List OpenSearch alerts filtered by severity / monitor / service / time. Pass `dataSourceId` (from `list_data_sources`) and any combination of `severity` (1-5), `monitorName`, `serviceName`, and `since` (ISO8601). Reads `.opensearch-alerting-alert-history-*` via PPL, sorted by `start_time` desc, capped at 200 rows.",
    inputSchema: inputSchema49
  },
  propsSchema: propsSchema49,
  view: FilterView,
  handler: async ({ dataSourceId, severity, monitorName, serviceName, since }, ctx) => {
    const filters = [];
    if (severity) filters.push(`where severity = "${quote(severity)}"`);
    if (monitorName && monitorName.trim()) {
      filters.push(`where monitor_name = "${quote(monitorName.trim())}"`);
    }
    if (serviceName && serviceName.trim()) {
      filters.push(`where service_name = "${quote(serviceName.trim())}"`);
    }
    if (since && since.trim()) {
      filters.push(`where start_time >= "${quote(since.trim())}"`);
    }
    const filterChain = filters.length ? ` | ${filters.join(" | ")}` : "";
    const query = `source = ${DATASET4}${filterChain} | sort - start_time | head ${DEFAULT_LIMIT9}`;
    ctx.logger.log("[alerts-feed.filter] PPL: " + query);
    const baseProps = { dataset: DATASET4, query };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET4);
      const alerts = pplRows(result).map((row, i7) => ({
        id: row.getString("alert_id") || row.getString("id") || `row-${i7}`,
        monitorName: row.getString("monitor_name"),
        triggerName: row.getString("trigger_name"),
        severity: row.getString("severity"),
        state: row.getString("state"),
        startTime: row.getString("start_time"),
        serviceName: row.getString("service_name"),
        message: row.getString("alert_info") || row.getString("message") || row.getString("trigger.message_template")
      }));
      const props = { ...baseProps, alerts };
      return {
        props,
        text: alerts.length === 0 ? "No alerts matched the filter." : `Loaded ${alerts.length} alert(s) matching filter.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[alerts-feed.filter] PPL failed: " + msg);
      const props = { ...baseProps, alerts: [], error: msg };
      return {
        props,
        text: "Failed to filter alerts: " + msg,
        isError: true
      };
    }
  }
});

