// src/apps/alerts-feed/unified/tool.ts
var DATASET6 = ".opensearch-alerting-alert-history-*";
var unifiedRoute = defineRoute({
  id: "unified",
  tool: {
    title: "Unified alerts (OpenSearch + Cortex)",
    description: "Show currently firing alerts from BOTH OpenSearch Alerting AND Cortex Alertmanager side-by-side. OpenSearch side reads `.opensearch-alerting-alert-history-*` via PPL; Cortex side falls back to `cortex-rule` saved objects when no live Alertmanager endpoint is configured. Pass `dataSourceId` (from `list_data_sources`).",
    inputSchema: inputSchema52
  },
  propsSchema: propsSchema52,
  view: UnifiedView,
  handler: async ({ dataSourceId }, ctx) => {
    const query = `source = ${DATASET6} | where state = "ACTIVE" | sort - start_time | head 100`;
    ctx.logger.log("[alerts-feed.unified] PPL: " + query);
    let opensearchAlerts = [];
    let opensearchError;
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET6);
      opensearchAlerts = pplRows(result).map((row, i7) => ({
        id: row.getString("alert_id") || row.getString("id") || `os-${i7}`,
        monitorName: row.getString("monitor_name"),
        triggerName: row.getString("trigger_name"),
        severity: row.getString("severity"),
        state: row.getString("state"),
        startTime: row.getString("start_time")
      }));
    } catch (err) {
      opensearchError = errorMessage(err);
      ctx.logger.error("[alerts-feed.unified] OS PPL failed: " + opensearchError);
    }
    let cortexAlerts = [];
    let cortexError;
    try {
      const raw = await ctx.osUi.findSavedObjects("cortex-rule", {
        dataSourceId,
        perPage: 100
      });
      cortexAlerts = raw.map((o3) => {
        const attrs = o3.attributes;
        const labels = attrs.labels ?? {};
        const annotations = attrs.annotations ?? {};
        const alertName = typeof attrs.alert === "string" ? attrs.alert : "";
        return {
          id: o3.id,
          ruleName: o3.title || alertName || o3.id,
          severity: typeof labels.severity === "string" ? labels.severity : "",
          state: typeof attrs.state === "string" ? attrs.state : "firing",
          description: o3.description || (typeof annotations.summary === "string" ? annotations.summary : "")
        };
      });
    } catch (err) {
      cortexError = errorMessage(err);
      ctx.logger.log(
        "[alerts-feed.unified] cortex-rule saved-objects lookup failed (likely not registered): " + cortexError
      );
    }
    const props = {
      dataset: DATASET6,
      query,
      opensearchAlerts,
      cortexAlerts,
      opensearchError,
      cortexError
    };
    const total = opensearchAlerts.length + cortexAlerts.length;
    return {
      props,
      text: total === 0 ? "No firing alerts in either OpenSearch Alerting or Cortex." : `${opensearchAlerts.length} OpenSearch + ${cortexAlerts.length} Cortex alert(s) firing.`
    };
  }
});

