// src/apps/anomaly-detection/feature-contribution/tool.ts
var DATASET7 = ".opendistro-anomaly-results-*";
var featureContributionRoute = defineRoute({
  id: "feature-contribution",
  tool: {
    title: "Feature contribution",
    description: "Inspect feature-level contributions for one anomaly result. Pass `dataSourceId`, `detectorId`, and `anomalyId` (the result document `_id`).",
    inputSchema: inputSchema55
  },
  propsSchema: propsSchema55,
  view: FeatureContributionView,
  handler: async ({ dataSourceId, detectorId, anomalyId }, ctx) => {
    const safeDetector = detectorId.replace(/"/g, '\\"');
    const safeAnomaly = anomalyId.replace(/"/g, '\\"');
    const query = `source = ${DATASET7} | where detector_id = "${safeDetector}" and _id = "${safeAnomaly}" | head 1`;
    ctx.logger.log("[anomaly-detection.feature-contribution] PPL: " + query);
    const baseProps = {
      dataset: DATASET7,
      detectorId,
      anomalyId,
      query,
      grade: 0,
      confidence: 0
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET7);
      const rows = pplRows(result);
      if (rows.length === 0) {
        const props2 = { ...baseProps, features: [] };
        return { props: props2, text: "Anomaly result not found." };
      }
      const row = rows[0];
      const grade = toNumber(row.get("anomaly_grade"));
      const confidence = toNumber(row.get("confidence"));
      const featureData = row.get("feature_data");
      const featureArr = Array.isArray(featureData) ? featureData : [];
      const features = featureArr.map((f8) => ({
        name: asString4(f8.feature_name) || asString4(f8.feature_id) || "\u2014",
        value: toNumber(f8.data),
        contribution: toNumber(f8.contribution)
      }));
      const props = {
        ...baseProps,
        grade,
        confidence,
        features
      };
      return {
        props,
        text: features.length === 0 ? "No feature_data on this anomaly." : `Loaded ${features.length} feature(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[anomaly-detection.feature-contribution] PPL failed: " + msg);
      const props = {
        ...baseProps,
        features: [],
        error: msg
      };
      return {
        props,
        text: "Failed to load feature contribution: " + msg,
        isError: true
      };
    }
  }
});

