// src/apps/anomaly-detection/grade-chart/tool.ts
var DATASET8 = ".opendistro-anomaly-results-*";
var gradeChartRoute = defineRoute({
  id: "grade-chart",
  tool: {
    title: "Anomaly grade chart",
    description: "Plot anomaly grade and confidence over time for one detector. Pass `dataSourceId` (from `list_data_sources`) and `detectorId` (from `anomaly-detection_list`); optional `intervalMinutes`.",
    inputSchema: inputSchema56
  },
  propsSchema: propsSchema56,
  view: GradeChartView,
  handler: async ({ dataSourceId, detectorId }, ctx) => {
    const safeId = detectorId.replace(/"/g, '\\"');
    const query = `source = ${DATASET8} | where detector_id = "${safeId}" | sort + execution_start_time | head 200`;
    ctx.logger.log("[anomaly-detection.grade-chart] PPL: " + query);
    const baseProps = {
      dataset: DATASET8,
      detectorId,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET8);
      const points = pplRows(result).map((row) => ({
        bucket: row.getString("execution_start_time"),
        grade: row.getNumber("anomaly_grade"),
        confidence: row.getNumber("confidence")
      }));
      const props = { ...baseProps, points };
      return {
        props,
        text: points.length === 0 ? "No anomaly results in range." : `Loaded ${points.length} bucket(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[anomaly-detection.grade-chart] PPL failed: " + msg);
      const props = { ...baseProps, points: [], error: msg };
      return {
        props,
        text: "Failed to load anomaly grades: " + msg,
        isError: true
      };
    }
  }
});

