// src/apps/anomaly-detection/list/tool.ts
var DATASET9 = ".opendistro-anomaly-detectors";
var listRoute7 = defineRoute({
  id: "list",
  tool: {
    title: "List anomaly detectors",
    description: "List OpenSearch anomaly detectors. Pass `dataSourceId` (from `list_data_sources`). Reads from `.opendistro-anomaly-detectors` via PPL.",
    inputSchema: inputSchema58
  },
  propsSchema: propsSchema58,
  view: ListView7,
  handler: async ({ dataSourceId }, ctx) => {
    const query = `source = ${DATASET9} | head 100`;
    ctx.logger.log("[anomaly-detection.list] PPL: " + query);
    const baseProps = { dataset: DATASET9, query };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET9);
      const detectors = pplRows(result).map((row, i7) => ({
        id: row.getString("_id") || row.getString("id") || `row-${i7}`,
        name: row.getString("name"),
        indices: row.getString("indices"),
        enabled: Boolean(row.get("enabled") ?? false),
        detectionInterval: row.getString("detection_interval")
      }));
      const props = { ...baseProps, detectors };
      return {
        props,
        text: detectors.length === 0 ? "No anomaly detectors found." : `Loaded ${detectors.length} detector(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[anomaly-detection.list] PPL failed: " + msg);
      const props = { ...baseProps, detectors: [], error: msg };
      return {
        props,
        text: "Failed to list detectors. The anomaly-detection plugin index may not exist on this cluster: " + msg,
        isError: true
      };
    }
  }
});

