// src/apps/anomaly-detection/overlay/tool.ts
var ANOMALY_DATASET = ".opendistro-anomaly-results-*";
var DEFAULT_INTERVAL = 5;
var overlayRoute = defineRoute({
  id: "overlay",
  tool: {
    title: "Anomaly + log overlay",
    description: "Overlay anomaly grade with log volume from a logs index for visual correlation. Pass `dataSourceId`, `detectorId`, and `logsDataset` (logs index pattern title); optional `intervalMinutes` (default 5).",
    inputSchema: inputSchema60
  },
  propsSchema: propsSchema60,
  view: OverlayView,
  handler: async ({ dataSourceId, detectorId, logsDataset, intervalMinutes }, ctx) => {
    const interval = intervalMinutes ?? DEFAULT_INTERVAL;
    const safeId = detectorId.replace(/"/g, '\\"');
    const anomalyQuery = `source = ${ANOMALY_DATASET} | where detector_id = "${safeId}" | stats max(anomaly_grade) as grade by span(execution_start_time, ${interval}m) as bucket | sort + bucket | head 200`;
    const logsQuery = `source = ${logsDataset} | stats count() as count by span(@timestamp, ${interval}m) as bucket | sort + bucket | head 200`;
    ctx.logger.log("[anomaly-detection.overlay] anomaly PPL: " + anomalyQuery);
    ctx.logger.log("[anomaly-detection.overlay] logs PPL: " + logsQuery);
    const baseProps = {
      detectorId,
      logsDataset,
      anomalyDataset: ANOMALY_DATASET,
      anomalyQuery,
      logsQuery,
      intervalMinutes: interval
    };
    try {
      const [anomalyResult, logsResult] = await Promise.all([
        ctx.osUi.runPpl(dataSourceId, anomalyQuery, ANOMALY_DATASET),
        ctx.osUi.runPpl(dataSourceId, logsQuery, logsDataset)
      ]);
      const anomalies = pplRows(anomalyResult).map((row) => ({
        bucket: row.getString("bucket"),
        grade: row.getNumber("grade")
      }));
      const logs = pplRows(logsResult).map((row) => ({
        bucket: row.getString("bucket"),
        count: row.getNumber("count")
      }));
      const props = { ...baseProps, anomalies, logs };
      return {
        props,
        text: `Loaded ${anomalies.length} anomaly bucket(s) and ${logs.length} log bucket(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[anomaly-detection.overlay] PPL failed: " + msg);
      const props = {
        ...baseProps,
        anomalies: [],
        logs: [],
        error: msg
      };
      return {
        props,
        text: "Failed to load overlay: " + msg,
        isError: true
      };
    }
  }
});

