// src/apps/apm-red/genai-tokens/tool.ts
var DEFAULT_DATASET11 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT11 = 10;
var genaiTokensRoute = defineRoute({
  id: "genai-tokens",
  tool: {
    title: "GenAI token usage",
    description: "Aggregate GenAI input / output token usage by model or agent. Pass `dataSourceId`; optional `dataset` (defaults `otel-v1-apm-span-*`), `groupBy` (`model` (default) | `agent`), and `limit` (default 10).",
    inputSchema: inputSchema67
  },
  propsSchema: propsSchema67,
  view: GenaiTokensView,
  handler: async ({ dataSourceId, dataset, groupBy: groupBy2, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET11;
    const lim = limit ?? DEFAULT_LIMIT11;
    const gb = groupBy2 ?? "model";
    const groupField = gb === "model" ? "attributes.gen_ai.request.model" : "attributes.gen_ai.agent.name";
    const query = `source = ${ds} | where attributes.gen_ai.usage.input_tokens > 0 | stats sum(attributes.gen_ai.usage.input_tokens) as inTok, sum(attributes.gen_ai.usage.output_tokens) as outTok by ${groupField} | sort - outTok | head ${lim}`;
    ctx.logger.log("[apm-red.genai-tokens] PPL: " + query);
    const baseProps = {
      dataset: ds,
      groupBy: gb,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result).map((r8) => {
        const inTok = r8.getNumber("inTok");
        const outTok = r8.getNumber("outTok");
        return {
          group: r8.getString(groupField) || "(unknown)",
          inputTokens: inTok,
          outputTokens: outTok,
          totalTokens: inTok + outTok
        };
      });
      const props = { ...baseProps, rows };
      return {
        props,
        text: rows.length === 0 ? `No GenAI token usage found in ${ds}.` : `Token usage by ${gb} (top ${rows.length}).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[apm-red.genai-tokens] PPL failed: " + msg);
      const props = { ...baseProps, rows: [], error: msg };
      return { props, text: "Failed: " + msg, isError: true };
    }
  }
});

