// src/apps/apm-red/top-ops-by-fault/tool.ts
var DEFAULT_DATASET12 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT12 = 10;
var topOpsByFaultRoute = defineRoute({
  id: "top-ops-by-fault",
  tool: {
    title: "Top operations by fault rate",
    description: "Rank a service's operations by fault rate (statusCode = 2). Pass `dataSourceId` and `serviceName`; optional `dataset` (defaults `otel-v1-apm-span-*`) and `limit` (default 10).",
    inputSchema: inputSchema68
  },
  propsSchema: propsSchema68,
  view: TopOpsByFaultView,
  handler: async ({ dataSourceId, dataset, serviceName, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET12;
    const lim = limit ?? DEFAULT_LIMIT12;
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | eval isErr = if(statusCode = 2, 1, 0) | stats count() as total, sum(isErr) as errors by name | eval faultRate = errors / total | sort - faultRate | head ${lim}`;
    ctx.logger.log("[apm-red.top-ops-by-fault] PPL: " + query);
    const baseProps = {
      dataset: ds,
      serviceName,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const ops = pplRows(result).map((r8) => {
        const total = r8.getNumber("total");
        const errors = r8.getNumber("errors");
        return {
          name: r8.getString("name") || "(unnamed)",
          total,
          errors,
          faultRate: total > 0 ? errors / total : 0
        };
      });
      const props = { ...baseProps, ops };
      return {
        props,
        text: ops.length === 0 ? `No operations found for ${serviceName} in ${ds}.` : `Top ${ops.length} op(s) by fault rate.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[apm-red.top-ops-by-fault] PPL failed: " + msg);
      const props = { ...baseProps, ops: [], error: msg };
      return { props, text: "Failed: " + msg, isError: true };
    }
  }
});

