// src/apps/apm-traces/error-types/tool.ts
var DEFAULT_DATASET13 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT13 = 20;
var ERROR_TYPE_FIELD = "attributes.error.type";
var errorTypesRoute = defineRoute({
  id: "error-types",
  tool: {
    title: "Span error types",
    description: "Group error spans (statusCode = 2) for a service by `error.type` and count occurrences. Pass `dataSourceId` and `serviceName`; optional `dataset` (defaults `otel-v1-apm-span-*`) and `limit` (default 20).",
    inputSchema: inputSchema70
  },
  propsSchema: propsSchema70,
  view: ErrorTypesView,
  handler: async ({ dataSourceId, dataset, serviceName, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET13;
    const lim = limit ?? DEFAULT_LIMIT13;
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | where statusCode = 2 | stats count() as count by ${ERROR_TYPE_FIELD} | sort - count | head ${lim}`;
    ctx.logger.log("[apm-traces.error-types] PPL: " + query);
    const baseProps = {
      dataset: ds,
      serviceName,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result).map((r8) => ({
        errorType: r8.getString(ERROR_TYPE_FIELD) || "(unspecified)",
        count: r8.getNumber("count")
      }));
      const props = { ...baseProps, rows };
      return {
        props,
        text: rows.length === 0 ? `No error spans for ${serviceName} in ${ds}.` : `Loaded ${rows.length} error type(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[apm-traces.error-types] PPL failed: " + msg);
      const props = { ...baseProps, rows: [], error: msg };
      return { props, text: "Failed: " + msg, isError: true };
    }
  }
});

