var DEFAULT_DATASET14 = "otel-v1-apm-span-*";
var listRoute8 = defineRoute({
  id: "list",
  tool: {
    title: "APM trace browser",
    description: "List recent root traces for a single service from a trace span index. Pass `dataSourceId` (from `list_data_sources`) and `serviceName`; optional `dataset` (the span index pattern title \u2014 discover via `list_index_patterns`, defaults to `otel-v1-apm-span-*`).",
    inputSchema: inputSchema71
  },
  propsSchema: propsSchema71,
  view: ListView8,
  handler: async ({ dataSourceId, dataset, serviceName }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET14;
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | where parentSpanId = "" | sort - startTime | head 100`;
    ctx.logger.log("[apm-traces.list] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      serviceName
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const traces = pplRows(result).map((row) => ({
        traceId: row.getString("traceId"),
        name: row.getString("name"),
        durationInNanos: row.getNumber("durationInNanos"),
        statusCode: row.getNumber("statusCode"),
        startTime: row.getString("startTime")
      }));
      const props = { ...baseProps, traces };
      return {
        props,
        text: traces.length === 0 ? `No root traces found for serviceName=${serviceName} in ${ds}.` : `Loaded ${traces.length} trace(s) for ${serviceName}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[apm-traces.list] PPL failed: " + msg);
      const props = { ...baseProps, traces: [], error: msg };
      return { props, text: "Failed to load traces: " + msg, isError: true };
    }
  }
});

