function safeParse4(s2) {
  if (typeof s2 !== "string") return null;
  try {
    return JSON.parse(s2);
  } catch {
    return null;
  }
}
var renderRoute = defineRoute({
  id: "render",
  tool: {
    title: "Render dashboard",
    description: "Render a dashboard's panels inside chat as a read-only grid. Required: `dataSourceId`, `dashboardId` (from `dashboards_list`).",
    inputSchema: inputSchema103
  },
  propsSchema: propsSchema103,
  view: RenderView,
  handler: async ({ dataSourceId, dashboardId }, ctx) => {
    try {
      const matches = await ctx.osUi.findSavedObjects("dashboard", {
        dataSourceId,
        search: dashboardId,
        perPage: 50
      });
      const dashboard = matches.find((m5) => m5.id === dashboardId) ?? matches[0] ?? null;
      if (!dashboard) {
        const props2 = {
          dataSourceId,
          dashboardId,
          dashboardTitle: dashboardId,
          description: "",
          panels: [],
          error: `Dashboard ${dashboardId} not found.`
        };
        return {
          props: props2,
          text: `Dashboard ${dashboardId} not found.`,
          isError: true
        };
      }
      const attrs = dashboard.attributes ?? {};
      const rawPanels = safeParse4(attrs.panelsJSON) ?? [];
      const refsById = new Map(
        (dashboard.references ?? []).map((r8) => [r8.name, r8])
      );
      const panels = await Promise.all(
        rawPanels.map(async (p4) => {
          const panelId = p4.panelIndex ?? p4.gridData?.i ?? "";
          const refName = `panel_${panelId}`;
          const ref = refsById.get(refName);
          const refType = ref?.type ?? p4.type ?? "visualization";
          const refId = ref?.id ?? "";
          const fallbackTitle = p4.title ?? p4.embeddableConfig?.title ?? "(untitled)";
          let vizType = "";
          let title = fallbackTitle;
          let query = "";
          if (refId) {
            try {
              const vizMatches = await ctx.osUi.findSavedObjects(refType, {
                dataSourceId,
                search: refId,
                perPage: 5
              });
              const viz = vizMatches.find((v3) => v3.id === refId) ?? vizMatches[0];
              if (viz) {
                const va = viz.attributes;
                title = va.title ?? title;
                const vis = safeParse4(va.visState);
                vizType = vis?.type ?? "";
                const ss = safeParse4(
                  va.kibanaSavedObjectMeta?.searchSourceJSON
                );
                query = ss?.query?.query ?? "";
              }
            } catch {
            }
          }
          return {
            panelId,
            title,
            vizType,
            savedObjectId: refId,
            savedObjectType: refType,
            query
          };
        })
      );
      const props = {
        dataSourceId,
        dashboardId: dashboard.id,
        dashboardTitle: dashboard.title,
        description: dashboard.description,
        panels
      };
      return {
        props,
        text: `Loaded ${panels.length} panel(s) for "${dashboard.title}".`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[dashboards.render] failed: " + msg);
      const props = {
        dataSourceId,
        dashboardId,
        dashboardTitle: dashboardId,
        description: "",
        panels: [],
        error: msg
      };
      return {
        props,
        text: "Failed to render dashboard: " + msg,
        isError: true
      };
    }
  }
});

