// src/apps/datasets-admin/list/tool.ts
var listRoute12 = defineRoute({
  id: "list",
  tool: {
    title: "List datasets",
    description: "List logs and traces datasets registered in OpenSearch. Optionally pass `dataSourceId` (from `list_data_sources`) to scope to one cluster.",
    inputSchema: inputSchema108
  },
  propsSchema: propsSchema108,
  view: ListView12,
  handler: async ({ dataSourceId }, ctx) => {
    try {
      let raw = await ctx.osUi.findSavedObjects("dataset", { dataSourceId });
      if (raw.length === 0) {
        raw = await ctx.osUi.findSavedObjects("dataset-management-dataset", {
          dataSourceId
        });
      }
      const datasets = raw.map((o3) => ({
        id: o3.id,
        title: o3.title,
        description: o3.description,
        type: String(
          o3.attributes?.type ?? o3.attributes?.signalType ?? o3.type
        )
      }));
      const props = { dataSourceId, datasets };
      return { props, text: `Found ${datasets.length} dataset(s).` };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[datasets-admin.list] failed: " + msg);
      const props = { dataSourceId, datasets: [], error: msg };
      return { props, text: "Failed to list datasets: " + msg, isError: true };
    }
  }
});

