var SAMPLE = `route:
  receiver: default-receiver
  group_by: [alertname, cluster]
  group_wait: 30s
  group_interval: 5m
  repeat_interval: 4h
  routes:
    - matchers:
        - team = platform
      receiver: pagerduty-platform
      routes:
        - matchers:
            - severity = critical
          receiver: pagerduty-platform-high
    - matchers:
        - team = data
      receiver: slack-data
    - matchers:
        - severity =~ "info|low"
      receiver: blackhole

receivers:
  - name: default-receiver
    email_configs:
      - to: oncall@example.com

  - name: pagerduty-platform
    pagerduty_configs:
      - service_key: \${PD_PLATFORM_KEY}

  - name: pagerduty-platform-high
    pagerduty_configs:
      - service_key: \${PD_PLATFORM_HIGH_KEY}
        severity: critical

  - name: slack-data
    slack_configs:
      - api_url: \${SLACK_DATA_WEBHOOK}
        channel: '#alerts-data'
        title: '{{ .CommonAnnotations.summary }}'
        text: '{{ .CommonAnnotations.description }}'

  - name: blackhole

inhibit_rules:
  - source_matchers: [severity = critical]
    target_matchers: [severity =~ "warning|info"]
    equal: [alertname, cluster]
`;
