// src/apps/destinations/list/tool.ts
var DATASET10 = ".opendistro-alerting-config";
var listRoute14 = defineRoute({
  id: "list",
  tool: {
    title: "List notification destinations",
    description: "List OpenSearch alerting notification destinations / channels (Slack / PagerDuty / email / webhook). Pass `dataSourceId` (from `list_data_sources`). Reads from `.opendistro-alerting-config` via PPL.",
    inputSchema: inputSchema117
  },
  propsSchema: propsSchema117,
  view: ListView14,
  handler: async ({ dataSourceId }, ctx) => {
    const query = `source = ${DATASET10} | where type = "notification_channel" | head 100`;
    ctx.logger.log("[destinations.list] PPL: " + query);
    const baseProps = { dataset: DATASET10, query };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET10);
      const destinations = pplRows(result).map((row, i7) => ({
        id: row.getString("_id") || row.getString("id") || `row-${i7}`,
        name: row.getString("notification_channel.name") || row.getString("name"),
        type: row.getString("notification_channel.type") || row.getString("channel_type"),
        description: row.getString("notification_channel.description") || row.getString("description")
      }));
      const props = { ...baseProps, destinations };
      return {
        props,
        text: destinations.length === 0 ? "No notification destinations found." : `Loaded ${destinations.length} destination(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[destinations.list] PPL failed: " + msg);
      const props = { ...baseProps, destinations: [], error: msg };
      return {
        props,
        text: "Failed to list destinations. The alerting config index may not exist on this cluster: " + msg,
        isError: true
      };
    }
  }
});

