// src/apps/forecasting/list/tool.ts
var DATASET11 = ".opendistro-forecaster";
var listRoute16 = defineRoute({
  id: "list",
  tool: {
    title: "List forecasters",
    description: "List OpenSearch forecasters. Pass `dataSourceId` (from `list_data_sources`). Reads from `.opendistro-forecaster` via PPL.",
    inputSchema: inputSchema123
  },
  propsSchema: propsSchema123,
  view: ListView16,
  handler: async ({ dataSourceId }, ctx) => {
    const query = `source = ${DATASET11} | head 100`;
    ctx.logger.log("[forecasting.list] PPL: " + query);
    const baseProps = { dataset: DATASET11, query };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET11);
      const forecasters = pplRows(result).map((row, i7) => ({
        id: row.getString("_id") || row.getString("id") || `row-${i7}`,
        name: row.getString("name"),
        horizon: row.getString("horizon") || row.getString("forecast_interval")
      }));
      const props = { ...baseProps, forecasters };
      return {
        props,
        text: forecasters.length === 0 ? "No forecasters found." : `Loaded ${forecasters.length} forecaster(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[forecasting.list] PPL failed: " + msg);
      const props = { ...baseProps, forecasters: [], error: msg };
      return {
        props,
        text: "Failed to list forecasters. The forecasting plugin index may not exist on this cluster: " + msg,
        isError: true
      };
    }
  }
});

