// src/apps/forecasting/predicted-values/tool.ts
var DATASET12 = ".opensearch-forecasting-result-*";
var predictedValuesRoute = defineRoute({
  id: "predicted-values",
  tool: {
    title: "Forecasted values",
    description: "Plot forecast values with confidence-interval band for one forecaster. Pass `dataSourceId` (from `list_data_sources`) and `forecasterId` (from `forecasting_list`).",
    inputSchema: inputSchema124
  },
  propsSchema: propsSchema124,
  view: PredictedValuesView,
  handler: async ({ dataSourceId, forecasterId }, ctx) => {
    const safeId = forecasterId.replace(/"/g, '\\"');
    const query = `source = ${DATASET12} | where forecaster_id = "${safeId}" | sort + data_start_time | head 200`;
    ctx.logger.log("[forecasting.predicted-values] PPL: " + query);
    const baseProps = {
      dataset: DATASET12,
      forecasterId,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET12);
      const points = pplRows(result).map((row) => {
        const predicted = row.getNumber("forecast_value");
        const upper = row.getNumber("upper_bound");
        const lower = row.getNumber("lower_bound");
        return {
          bucket: row.getString("data_start_time"),
          predicted,
          upper: upper || predicted,
          lower: lower || predicted
        };
      });
      const props = { ...baseProps, points };
      return {
        props,
        text: points.length === 0 ? "No forecast results in range." : `Loaded ${points.length} forecast bucket(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[forecasting.predicted-values] PPL failed: " + msg);
      const props = { ...baseProps, points: [], error: msg };
      return {
        props,
        text: "Failed to load forecast: " + msg,
        isError: true
      };
    }
  }
});

