// src/apps/index-patterns-admin/field-mappings/tool.ts
var fieldMappingsRoute = defineRoute({
  id: "field-mappings",
  tool: {
    title: "Inspect field mappings",
    description: "List the field name + type for an index pattern using PPL `describe`. Pass `dataSourceId` (from `list_data_sources`) and `indexPattern` (title \u2014 discover via `list_index_patterns`).",
    inputSchema: inputSchema128
  },
  propsSchema: propsSchema128,
  view: FieldMappingsView,
  handler: async ({ dataSourceId, indexPattern }, ctx) => {
    const ds = indexPattern.trim();
    const query = `describe ${ds}`;
    ctx.logger.log("[index-patterns-admin.field-mappings] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const fields = pplRows(result).map((r8) => {
        const name = r8.getString("COLUMN_NAME") || r8.getString("FIELD_NAME") || r8.getString("name") || "";
        const type = r8.getString("DATA_TYPE") || r8.getString("TYPE") || r8.getString("type") || "";
        return { name, type };
      });
      const props = {
        dataSourceId,
        indexPattern: ds,
        query,
        fields
      };
      return {
        props,
        text: fields.length === 0 ? `No fields described for ${ds}.` : `Loaded ${fields.length} field(s) for ${ds}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[index-patterns-admin.field-mappings] failed: " + msg);
      const props = {
        dataSourceId,
        indexPattern: ds,
        query,
        fields: [],
        error: msg
      };
      return {
        props,
        text: "Failed to describe index pattern: " + msg,
        isError: true
      };
    }
  }
});

