var listRoute17 = defineRoute({
  id: "list",
  tool: {
    title: "List index patterns",
    description: "List index patterns scoped to a data source. Pass `dataSourceId` (from `list_data_sources`); without it, returns an empty list with a hint.",
    inputSchema: inputSchema129
  },
  propsSchema: propsSchema129,
  view: ListView17,
  handler: async ({ dataSourceId }, ctx) => {
    if (!dataSourceId) {
      const props = {
        patterns: [],
        hint: "Pass dataSourceId (from list_data_sources) to scope the lookup."
      };
      return { props, text: "Pass dataSourceId to list index patterns." };
    }
    try {
      const patterns = await ctx.osUi.listIndexPatterns(dataSourceId);
      const props = { dataSourceId, patterns };
      return { props, text: `Found ${patterns.length} index pattern(s).` };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[index-patterns-admin.list] failed: " + msg);
      const props = { dataSourceId, patterns: [], error: msg };
      return { props, text: "Failed to list index patterns: " + msg, isError: true };
    }
  }
});

