// src/apps/index-patterns-admin/signal-badges/tool.ts
function classify(title) {
  const t2 = title.toLowerCase();
  if (t2.includes("otel-v1-apm-span") || t2.includes("otel-v2-apm-service-map"))
    return "traces";
  if (t2.includes("span") || t2.includes("trace")) return "traces";
  if (t2.includes("logs-otel-v1") || t2.includes("log")) return "logs";
  if (t2.includes("metric")) return "metrics";
  return "other";
}
var signalBadgesRoute = defineRoute({
  id: "signal-badges",
  tool: {
    title: "Index pattern signal badges",
    description: "List index patterns and tag each with its signal type (traces / logs / metrics / other) based on the title. Pass `dataSourceId` (from `list_data_sources`).",
    inputSchema: inputSchema130
  },
  propsSchema: propsSchema130,
  view: SignalBadgesView,
  handler: async ({ dataSourceId }, ctx) => {
    try {
      const raw = await ctx.osUi.listIndexPatterns(dataSourceId);
      const patterns = raw.map((p4) => ({
        id: p4.id,
        title: p4.title,
        timeFieldName: p4.timeFieldName,
        signal: classify(p4.title || "")
      }));
      const counts = {
        traces: patterns.filter((p4) => p4.signal === "traces").length,
        logs: patterns.filter((p4) => p4.signal === "logs").length,
        metrics: patterns.filter((p4) => p4.signal === "metrics").length,
        other: patterns.filter((p4) => p4.signal === "other").length
      };
      const props = { dataSourceId, patterns, counts };
      return {
        props,
        text: `Classified ${patterns.length} pattern(s): ${counts.traces} traces, ${counts.logs} logs, ${counts.metrics} metrics, ${counts.other} other.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[index-patterns-admin.signal-badges] failed: " + msg);
      const props = {
        dataSourceId,
        patterns: [],
        counts: { traces: 0, logs: 0, metrics: 0, other: 0 },
        error: msg
      };
      return {
        props,
        text: "Failed to classify index patterns: " + msg,
        isError: true
      };
    }
  }
});

