    const m5 = method ?? DEFAULT_METHOD2;
    const lim = limit ?? DEFAULT_LIMIT16;
    const query = buildQuery(ds, field, filter, m5, lim);
    const baseProps = {
      dataset: ds,
      patternsField: field,
      query
    };
    ctx.logger.log("[log-patterns.rare] PPL: " + query);
