var DEFAULT_LIMIT19 = 200;
var exploreRoute = defineRoute({
  id: "explore",
  tool: {
    title: "Logs explorer",
    description: 'Query an OpenSearch logs index with PPL and render a fielded log table with severity highlighting. Pass `dataSourceId` (from `list_data_sources`) and `dataset` (the logs index pattern title \u2014 discover via `list_index_patterns`). Optionally supply `query` (the PPL chain after `source = <dataset>`, e.g. `where severity = "ERROR"`) and `limit` (default 200).',
    inputSchema: inputSchema135
  },
  propsSchema: propsSchema135,
  view: ExploreView,
  handler: async ({ dataSourceId, dataset, query, limit }, ctx) => {
    const ds = dataset.trim();
    const lim = limit ?? DEFAULT_LIMIT19;
    const tail = (query ?? "").trim();
    const fullQuery = tail ? `source = ${ds} | ${tail.replace(/^\|\s*/, "")} | head ${lim}` : `source = ${ds} | head ${lim}`;
    ctx.logger.log("[logs.explore] PPL: " + fullQuery);
    const baseProps = {
      dataset: ds,
      query: fullQuery
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, fullQuery, ds);
      const fields = result.schema.map((f8) => ({ name: f8.name, type: f8.type }));
      const rows = result.datarows.map((row) => {
        const obj = {};
        fields.forEach((f8, i7) => {
          obj[f8.name] = row[i7];
        });
        return obj;
      });
      const props = {
        ...baseProps,
        fields,
        rows,
        total: result.total ?? rows.length
      };
      return {
        props,
        text: rows.length === 0 ? `No log rows for query against ${ds}.` : `Loaded ${rows.length} row(s) from ${ds}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[logs.explore] PPL failed: " + msg);
      return {
        props: { ...baseProps, fields: [], rows: [], total: 0, error: msg },
        text: "Failed to load logs: " + msg,
        isError: true
      };
    }
  }
});

