var DEFAULT_INTERVAL2 = 5;
var SEVERITY_VALUES = {
  error: ["ERROR", "FATAL", "CRITICAL"],
  warn: ["WARN", "WARNING"],
  info: ["INFO", "NOTICE"],
  debug: ["DEBUG", "TRACE"]
};
function severityFilter(severity) {
  if (severity === "any") return "";
  const values = SEVERITY_VALUES[severity];
  const ors = values.map((v3) => `severity = "${v3}"`).join(" or ");
  return ` | where ${ors}`;
}
var histogramRoute = defineRoute({
  id: "histogram",
  tool: {
    title: "Logs histogram",
    description: "Render a log volume histogram over time using PPL `span()` bucketing. Pass `dataSourceId` (from `list_data_sources`), `dataset` (logs index pattern title \u2014 discover via `list_index_patterns`). Optional `intervalMinutes` (default 5) and `severity` filter (`error`|`warn`|`info`|`debug`|`any`).",
    inputSchema: inputSchema136
  },
  propsSchema: propsSchema136,
  view: HistogramView,
  handler: async ({ dataSourceId, dataset, intervalMinutes, severity }, ctx) => {
    const ds = dataset.trim();
    const interval = intervalMinutes ?? DEFAULT_INTERVAL2;
    const sev = severity ?? "any";
    const sevChain = severityFilter(sev);
    const query = `source = ${ds}${sevChain} | stats count() as docs by span(@timestamp, ${interval}m) as bucket | sort + bucket`;
    ctx.logger.log("[logs.histogram] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      intervalMinutes: interval,
      severity: sev
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const buckets = pplRows(result).map((r8) => ({
        bucket: r8.getString("bucket"),
        docs: r8.getNumber("docs")
      }));
      const total = buckets.reduce((sum, b7) => sum + b7.docs, 0);
      const props = { ...baseProps, buckets, total };
      return {
        props,
        text: buckets.length === 0 ? `No log volume in ${ds}.` : `Loaded ${buckets.length} bucket(s) covering ${total} log(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[logs.histogram] PPL failed: " + msg);
      return {
        props: { ...baseProps, buckets: [], total: 0, error: msg },
        text: "Failed to load histogram: " + msg,
        isError: true
      };
    }
  }
});

