var TYPES3 = [
  {
    type: "Counter",
    definition: "Monotonically increasing cumulative value (resets to 0 on process restart). Use for events, requests, errors, bytes.",
    validOps: ["rate()", "irate()", "increase()", "sum()", "topk()"],
    example: "rate(http_requests_total[5m])"
  },
  {
    type: "Gauge",
    definition: "A value that can go up or down. Use for in-flight requests, queue depth, temperature, memory in use.",
    validOps: [
      "avg()",
      "min()",
      "max()",
      "sum()",
      "delta()",
      "deriv()",
      "predict_linear()"
    ],
    example: "avg(node_memory_MemAvailable_bytes) by (instance)"
  },
  {
    type: "Histogram",
    definition: "Cumulative bucketed observations: `_bucket{le=...}`, `_sum`, `_count`. Use for latency / request size distributions.",
    validOps: [
      "histogram_quantile()",
      "rate(_bucket)",
      "rate(_sum)",
      "rate(_count)"
    ],
    example: "histogram_quantile(0.99, sum by (le) (rate(http_request_duration_seconds_bucket[5m])))"
  },
  {
    type: "Summary",
    definition: "Client-side computed quantiles: `{quantile=...}`, `_sum`, `_count`. Quantiles are NOT aggregatable across instances.",
    validOps: ["rate(_sum)", "rate(_count)", "direct quantile read"],
    example: 'rpc_durations_seconds{quantile="0.99"}'
  }
];
