// src/apps/metrics-view/latest-values/tool.ts
var DEFAULT_DATASET16 = "prometheus.metrics";
var DEFAULT_LIMIT21 = 50;
var latestValuesRoute = defineRoute({
  id: "latest-values",
  tool: {
    title: "Latest values per series",
    description: "List the latest value of each label-combination series for a metric. Pass `dataSourceId` and `metricName`; optional `dataset` (defaults to `prometheus.metrics`) and `limit` (defaults to 50). Falls back to `stats max(@timestamp), avg(value)` grouping when the index doesn't expose per-row labels \u2014 if the index doesn't exist, returns an empty list with the failed PPL surfaced for review.",
    inputSchema: inputSchema151
  },
  propsSchema: propsSchema151,
  view: LatestValuesView,
  handler: async ({ dataSourceId, dataset, metricName, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET16;
    const lim = limit ?? DEFAULT_LIMIT21;
    const safeName = metricName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where __name__ = "${safeName}" | stats max(@timestamp) as lastSeen, latest(value) as lastValue by labels | sort - lastSeen | head ${lim}`;
    ctx.logger.log("[metrics-view.latest-values] PPL: " + query);
    const baseProps = {
      dataset: ds,
      metricName,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result).map((r8) => ({
        series: r8.getString("labels"),
        lastValue: r8.getString("lastValue"),
        lastSeen: r8.getString("lastSeen")
      }));
      const props = { ...baseProps, rows };
      return {
        props,
        text: rows.length === 0 ? `No series for ${metricName} in ${ds}.` : `Loaded ${rows.length} series for ${metricName}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[metrics-view.latest-values] PPL failed: " + msg);
      const props = {
        ...baseProps,
        rows: [],
        notice: "PPL did not execute against this dataset. If your stack doesn't expose Prometheus via PPL, use OpenSearch Dashboards' Metrics Explorer or `metrics-view.query` directly.",
        error: msg
      };
      return {
        props,
        text: "Failed to load series: " + msg,
        isError: true
      };
    }
  }
});

