// src/apps/metrics-view/multi-query/tool.ts
var COMPOSERS = [
  {
    operator: "or",
    meaning: "Set union. Series from the left are kept; series only in the right are added. Useful for combining two sources of the same signal.",
    example: 'up{job="api"} or up{job="web"}'
  },
  {
    operator: "and",
    meaning: "Set intersection. Keeps left-side series whose labels match a right-side series. Useful as a filter.",
    example: "rate(http_requests_total[5m]) and on (job) job:slo_target"
  },
  {
    operator: "unless",
    meaning: "Set complement. Keeps left-side series that have NO matching right-side series. Useful for `is_firing AND NOT silenced`.",
    example: 'ALERTS{alertstate="firing"} unless on (alertname) silenced_rules'
  },
  {
    operator: "+ - * / % ^",
    meaning: "Arithmetic between vectors (matched by labels) or against a scalar. Use `on(...)` / `ignoring(...)` to control matching.",
    example: "rate(errors_total[5m]) / rate(requests_total[5m])"
  },
  {
    operator: "== != > < >= <=",
    meaning: "Comparison. Returns left-side series where the comparison holds (or 0/1 with `bool`). Useful for filtering and alerting.",
    example: "(rate(errors_total[5m]) / rate(requests_total[5m])) > 0.05"
  }
];
var multiQueryRoute = defineRoute({
  id: "multi-query",
  tool: {
    title: "PromQL multi-query reference",
    description: "Reference card for rendering multiple PromQL expressions on one chart. Pass `dataSourceId` and `queries: string[]`. NOTE: PromQL execution is not wired in this build \u2014 the tool surfaces queries side-by-side and documents the binary / set operators (`or`, `and`, `unless`, arithmetic, comparison) used to compose them.",
    inputSchema: inputSchema152
  },
  propsSchema: propsSchema152,
  view: MultiQueryView,
  handler: async ({ dataSourceId, queries }, ctx) => {
    ctx.logger.log(
      `[metrics-view.multi-query] ${queries.length} PromQL expr(s) staged`
    );
    const notice = "PromQL execution requires Prometheus integration which isn't wired in this build. Queries are shown for review; binary operators below describe how they would compose.";
    const props = {
      dataSourceId,
      queries,
      composers: COMPOSERS,
      notice
    };
    return { props, text: `Staged ${queries.length} PromQL expr(s).` };
  }
});

