var SAMPLE_YAML = `groups:
  - name: prometheus_target_health
    interval: 30s
    rules:
      - alert: PrometheusTargetDown
        expr: up == 0
        for: 5m
        labels:
          severity: critical
          team: platform
        annotations:
          summary: "Prometheus target {{ $labels.instance }} is down"
          description: "Target {{ $labels.job }}/{{ $labels.instance }} has been unreachable for more than 5 minutes."
          runbook_url: https://runbooks.example.com/prometheus-target-down
`;
var KEY_DOCS = [
  {
    key: "groups:",
    meaning: "Top-level list of rule groups. Each group is evaluated together at its `interval`."
  },
  {
    key: "alert:",
    meaning: "Human-friendly name of the alert. Becomes the `alertname` label on the resulting series."
  },
  {
    key: "expr:",
    meaning: "PromQL expression. The rule fires for each set of labels where the expression evaluates to true (non-empty)."
  },
  {
    key: "for:",
    meaning: "How long the expression must remain true before the alert transitions from `pending` to `firing`. Suppresses flap."
  },
  {
    key: "labels:",
    meaning: "Static labels merged onto the firing series. Used by Alertmanager routing (e.g. `severity`, `team`)."
  },
  {
    key: "annotations:",
    meaning: "Free-form metadata (`summary`, `description`, `runbook_url`). Templated with `{{ $labels.* }}` and `{{ $value }}`."
  }
];
var cortexYamlRoute = defineRoute({
  id: "cortex-yaml",
  tool: {
    title: "Cortex / PromQL alerting rule (YAML reference)",
    description: "Reference page: a sample Cortex / PromQL alerting rule in YAML, with key-by-key explanations of `groups:`, `alert:`, `expr:`, `for:`, `labels:`, and `annotations:`. Use when authoring rules to load into Cortex Ruler.",
    inputSchema: inputSchema156
  },
  propsSchema: propsSchema156,
  view: CortexYamlView,
  handler: async () => {
    const props = {
      yaml: SAMPLE_YAML,
      description: "Cortex (and Prometheus) alerting rules are grouped under `groups:`. Each group fires its rules together at the group `interval`. The `expr:` is PromQL; while it evaluates non-empty, the rule is `pending` for `for:` then transitions to `firing`.",
      keys: KEY_DOCS
    };
    return { props, text: "Cortex / PromQL alerting rule reference." };
  }
});

