// src/apps/saved-objects-browser/apm-correlations/tool.ts
var APM_PRESET_TYPES = ["trace-to-logs-config", "APM-Config"];
var apmCorrelationsRoute = defineRoute({
  id: "apm-correlations",
  tool: {
    title: "Find APM correlations",
    description: "Filter saved objects to APM presets (`trace-to-logs-config` and `APM-Config`). Optionally pass `dataSourceId` (from `list_data_sources`).",
    inputSchema: inputSchema167
  },
  propsSchema: propsSchema167,
  view: ApmCorrelationsView,
  handler: async ({ dataSourceId }, ctx) => {
    try {
      const results = await Promise.all(
        APM_PRESET_TYPES.map(
          (t2) => ctx.osUi.findSavedObjects(t2, { dataSourceId, perPage: 200 })
        )
      );
      const merged = results.flat().map((o3) => ({
        id: o3.id,
        type: o3.type,
        title: o3.title,
        description: o3.description
      }));
      const props = {
        dataSourceId,
        savedObjects: merged
      };
      return {
        props,
        text: `Found ${merged.length} APM saved object(s) across ${APM_PRESET_TYPES.length} type(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[saved-objects-browser.apm-correlations] failed: " + msg);
      const props = {
        dataSourceId,
        savedObjects: [],
        error: msg
      };
      return {
        props,
        text: "Failed to find APM saved objects: " + msg,
        isError: true
      };
    }
  }
});

