// src/apps/saved-objects-browser/detail/tool.ts
var detailRoute3 = defineRoute({
  id: "detail",
  tool: {
    title: "Saved object detail",
    description: "Show the raw JSON for one saved object. Pass `type` (e.g. `dashboard`) and `objectId`; optionally `dataSourceId` for types that reference a data source.",
    inputSchema: inputSchema168
  },
  propsSchema: propsSchema168,
  view: DetailView3,
  handler: async ({ dataSourceId, type, objectId }, ctx) => {
    try {
      const matches = await ctx.osUi.findSavedObjects(type, {
        dataSourceId,
        search: objectId,
        perPage: 100
      });
      const exact = matches.find((o3) => o3.id === objectId) ?? null;
      if (!exact) {
        const props2 = {
          type,
          objectId,
          title: "",
          description: "",
          raw: null,
          found: false
        };
        return {
          props: props2,
          text: `No saved object of type \`${type}\` with id \`${objectId}\`.`
        };
      }
      const raw = {
        id: exact.id,
        type: exact.type,
        attributes: exact.attributes,
        references: exact.references
      };
      const props = {
        type: exact.type,
        objectId: exact.id,
        title: exact.title,
        description: exact.description,
        raw,
        found: true
      };
      return {
        props,
        text: `Loaded ${exact.type}/${exact.id}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[saved-objects-browser.detail] failed: " + msg);
      const props = {
        type,
        objectId,
        title: "",
        description: "",
        raw: null,
        found: false,
        error: msg
      };
      return {
        props,
        text: "Failed to load saved object: " + msg,
        isError: true
      };
    }
  }
});

