// src/apps/saved-objects-browser/list/tool.ts
var listRoute20 = defineRoute({
  id: "list",
  tool: {
    title: "Browse saved objects",
    description: "Generic saved-objects finder. Pass `type` (e.g. `dashboard`, `visualization`, `index-pattern`, `query`, `dataset`) and optionally `dataSourceId` from `list_data_sources` to scope to one cluster.",
    inputSchema: inputSchema169
  },
  propsSchema: propsSchema169,
  view: ListView20,
  handler: async ({ type, dataSourceId }, ctx) => {
    const t2 = (type || "dashboard").trim() || "dashboard";
    try {
      const raw = await ctx.osUi.findSavedObjects(t2, { dataSourceId, perPage: 200 });
      const savedObjects = raw.map((o3) => ({
        id: o3.id,
        type: o3.type,
        title: o3.title,
        description: o3.description
      }));
      const props = { type: t2, dataSourceId, savedObjects };
      return { props, text: `Found ${savedObjects.length} ${t2} saved object(s).` };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[saved-objects-browser.list] failed: " + msg);
      const props = { type: t2, dataSourceId, savedObjects: [], error: msg };
      return { props, text: "Failed to list saved objects: " + msg, isError: true };
    }
  }
});

