// src/apps/services/alert-prefill/tool.ts
var DEFAULT_DATASET17 = "otel-v1-apm-span-*";
var NANOS_PER_MS3 = 1e6;
var RECENT_ERROR_LIMIT = 20;
function quote2(s2) {
  return s2.replace(/"/g, '\\"');
}
var alertPrefillRoute = defineRoute({
  id: "alert-prefill",
  tool: {
    title: "Alert evidence pre-fill",
    description: "Pre-fill the service detail with the alert's evidence: 5 service KPIs (throughput, fault rate, error rate, availability, p99 latency) plus the most recent error spans (statusCode = 2) in the alert window. Pass `dataSourceId` (from `list_data_sources`) and `serviceName`; optional `alertId`, `since`, `until` (ISO 8601), and `dataset` (default `otel-v1-apm-span-*`).",
    inputSchema: inputSchema171
  },
  propsSchema: propsSchema171,
  view: AlertPrefillView,
  handler: async ({ dataSourceId, dataset, serviceName, alertId, since, until }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET17;
    const safeSvc = quote2(serviceName);
    const wheres = [`serviceName = "${safeSvc}"`];
    if (since && since.trim()) {
      wheres.push(`startTime >= "${quote2(since.trim())}"`);
    }
    if (until && until.trim()) {
      wheres.push(`startTime <= "${quote2(until.trim())}"`);
    }
    const whereChain = wheres.map((w2) => `where ${w2}`).join(" | ");
    const kpiQuery = `source = ${ds} | ${whereChain} | eval isErr = if(statusCode = 2, 1, 0) | eval isFault = if(statusCode >= 2, 1, 0) | stats count() as throughput, sum(isErr) as errors, sum(isFault) as faults, percentile(durationInNanos, 99) as p99`;
    ctx.logger.log("[services.alert-prefill] KPI PPL: " + kpiQuery);
    const errorsQuery = `source = ${ds} | ${whereChain} | where statusCode = 2 | sort - startTime | head ${RECENT_ERROR_LIMIT}`;
    ctx.logger.log("[services.alert-prefill] errors PPL: " + errorsQuery);
    const baseProps = {
      dataset: ds,
      serviceName,
      alertId,
      since,
      until,
      kpiQuery,
      errorsQuery
    };
    let throughput = 0;
    let faultRate = 0;
    let errorRate = 0;
    let availability = 1;
    let p99LatencyMs = 0;
    let kpiError;
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, kpiQuery, ds);
      const rows = pplRows(result);
      const row = rows[0];
      throughput = row?.getNumber("throughput") ?? 0;
      const errors = row?.getNumber("errors") ?? 0;
      const faults = row?.getNumber("faults") ?? 0;
      const p99Nanos = row?.getNumber("p99") ?? 0;
      errorRate = throughput > 0 ? errors / throughput : 0;
      faultRate = throughput > 0 ? faults / throughput : 0;
      availability = throughput > 0 ? 1 - errorRate : 1;
      p99LatencyMs = p99Nanos / NANOS_PER_MS3;
    } catch (err) {
      kpiError = errorMessage(err);
      ctx.logger.error("[services.alert-prefill] KPI PPL failed: " + kpiError);
    }
    let recentErrors = [];
    let errorsError;
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, errorsQuery, ds);
      recentErrors = pplRows(result).map((r8) => ({
        spanId: r8.getString("spanId"),
        traceId: r8.getString("traceId"),
        name: r8.getString("name"),
        startTime: r8.getString("startTime"),
        durationInNanos: r8.getNumber("durationInNanos")
      }));
    } catch (err) {
      errorsError = errorMessage(err);
      ctx.logger.error(
        "[services.alert-prefill] errors PPL failed: " + errorsError
      );
    }
    const combinedError = kpiError && errorsError ? `KPI: ${kpiError}; errors: ${errorsError}` : kpiError ?? errorsError;
    const props = {
      ...baseProps,
      throughput,
      faultRate,
      errorRate,
      availability,
      p99LatencyMs,
      recentErrors,
      error: combinedError
    };
    const isError = !!(kpiError && errorsError);
    const text = isError ? `Alert pre-fill failed: ${combinedError}` : `Loaded alert evidence for ${serviceName}: ${recentErrors.length} recent error span(s).`;
    return { props, text, isError };
  }
});

