var DEFAULT_DATASET18 = "otel-v1-apm-span-*";
var availabilityOpsRoute = defineRoute({
  id: "availability-ops",
  tool: {
    title: "Bottom operations by availability",
    description: "Bottom-K operations of a service by availability (1 - error rate). Pass `dataSourceId` (from `list_data_sources`) and `serviceName`; optional `dataset` (the span index pattern \u2014 discover via `list_index_patterns`, defaults to `otel-v1-apm-span-*`) and `bottomK` (`3` | `5` | `10`, default `5`).",
    inputSchema: inputSchema173
  },
  propsSchema: propsSchema173,
  view: AvailabilityOpsView,
  handler: async ({ dataSourceId, dataset, serviceName, bottomK }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET18;
    const k8 = bottomK ?? "5";
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | eval isErr = if(statusCode = 2, 1, 0) | stats count() as callCount, sum(isErr) as errorCount by name`;
    ctx.logger.log("[services.availability-ops] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      serviceName,
      bottomK: k8
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const all = pplRows(result).map((r8) => {
        const calls = r8.getNumber("callCount");
        const errors = r8.getNumber("errorCount");
        return {
          operation: r8.getString("name"),
          callCount: calls,
          errorCount: errors,
          availability: calls > 0 ? 1 - errors / calls : 1
        };
      });
      all.sort((a7, b7) => a7.availability - b7.availability);
      const rows = all.slice(0, Number(k8));
      const props = { ...baseProps, rows };
      return {
        props,
        text: rows.length === 0 ? `No operations for ${serviceName} in ${ds}.` : `Bottom ${rows.length} operations by availability.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[services.availability-ops] PPL failed: " + msg);
      const props = { ...baseProps, rows: [], error: msg };
      return { props, text: "Failed to load operations: " + msg, isError: true };
    }
  }
});

