// src/apps/services/catalog/tool.ts
var DEFAULT_LIMIT23 = 50;
var NANOS_PER_MS4 = 1e6;
var catalogRoute = defineRoute({
  id: "catalog",
  tool: {
    title: "Service catalog",
    description: "List services from a trace span index with RED-style KPIs (span count, error rate, avg/p50/p95/p99 latency). Pass `dataSourceId` (from `list_data_sources`) and `dataset` (the span index pattern, e.g. `otel-v1-apm-span-*` \u2014 discover via `list_index_patterns`); optionally override `limit` (default 50).",
    inputSchema: inputSchema174
  },
  propsSchema: propsSchema174,
  view: CatalogView,
  handler: async ({ dataSourceId, dataset, limit }, ctx) => {
    const ds = dataset.trim();
    const lim = limit ?? DEFAULT_LIMIT23;
    const query = `source = ${ds} | where serviceName != "" | eval isErr = if(statusCode = 2, 1, 0) | stats count() as spanCount, sum(isErr) as errorCount, avg(durationInNanos) as avgDur, percentile(durationInNanos, 50) as p50, percentile(durationInNanos, 95) as p95, percentile(durationInNanos, 99) as p99 by serviceName | sort - spanCount | head ${lim}`;
    ctx.logger.log("[services.catalog] PPL: " + query);
    const baseProps = { dataset: ds, query };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const services = [];
      for (const row of pplRows(result)) {
        const serviceName = row.getString("serviceName");
        if (!serviceName) continue;
        const spanCount = row.getNumber("spanCount");
        const errorCount = row.getNumber("errorCount");
        services.push({
          serviceName,
          spanCount,
          errorCount,
          errorRate: spanCount > 0 ? errorCount / spanCount : 0,
          avgLatencyMs: row.getNumber("avgDur") / NANOS_PER_MS4,
          p50LatencyMs: row.getNumber("p50") / NANOS_PER_MS4,
          p95LatencyMs: row.getNumber("p95") / NANOS_PER_MS4,
          p99LatencyMs: row.getNumber("p99") / NANOS_PER_MS4
        });
      }
      const props = { ...baseProps, services };
      return {
        props,
        text: services.length === 0 ? `No services found in ${ds}.` : `Loaded ${services.length} service(s) from ${ds}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[services.catalog] PPL failed: " + msg);
      const props = { ...baseProps, services: [], error: msg };
      return { props, text: "Failed to load services: " + msg, isError: true };
    }
  }
});

