    const sds = spansDataset?.trim() || DEFAULT_SPANS_DATASET2;
    const lds = logsDataset.trim();
    const lim = limit ?? DEFAULT_LIMIT25;
    const safeSvc = quote5(serviceName);
    const safeOp = quote5(operationName);
    const spansFilters = [`where serviceName = "${safeSvc}"`, `where name = "${safeOp}"`];
    if (traceId) spansFilters.push(`where traceId = "${quote5(traceId)}"`);
    const spansQuery = `source = ${sds} | ${spansFilters.join(" | ")} | sort - durationInNanos | head ${lim}`;
    ctx.logger.log("[services.correlation] spans PPL: " + spansQuery);
    let spans = [];
    let spansError;
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, spansQuery, sds);
      spans = pplRows(result).map((r8) => ({
        spanId: r8.getString("spanId"),
        traceId: r8.getString("traceId"),
        name: r8.getString("name"),
        serviceName: r8.getString("serviceName"),
        durationInNanos: r8.getNumber("durationInNanos"),
        statusCode: r8.getNumber("statusCode"),
        startTime: r8.getString("startTime")
      }));
    } catch (err) {
      spansError = errorMessage(err);
      ctx.logger.error("[services.correlation] spans PPL failed: " + spansError);
    }
    const traceIds = Array.from(new Set(spans.map((s2) => s2.traceId).filter(Boolean)));
    let logsQuery;
    let logs = [];
    let logsError;
    if (traceIds.length === 0) {
      logsQuery = `source = ${lds} | head 0`;
      ctx.logger.log("[services.correlation] no trace ids, skipping logs query");
    } else {
      const inClause = traceIds.map((t2) => `"${quote5(t2)}"`).join(", ");
      logsQuery = `source = ${lds} | where traceId in (${inClause}) | sort - \`@timestamp\` | head ${lim}`;
      ctx.logger.log("[services.correlation] logs PPL: " + logsQuery);
      try {
        const result = await ctx.osUi.runPpl(dataSourceId, logsQuery, lds);
        logs = pplRows(result).map((r8) => ({
          timestamp: r8.getString("@timestamp") || r8.getString("timestamp") || r8.getString("time"),
          severity: r8.getString("severityText") || r8.getString("severity") || r8.getString("level"),
          body: r8.getString("body") || r8.getString("message"),
          traceId: r8.getString("traceId"),
          serviceName: r8.getString("serviceName")
        }));
      } catch (err) {
        logsError = errorMessage(err);
        ctx.logger.error("[services.correlation] logs PPL failed: " + logsError);
      }
    }
