// src/apps/services/dependencies/tool.ts
var DEFAULT_DATASET20 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT26 = 100;
var NANOS_PER_MS7 = 1e6;
var dependenciesRoute = defineRoute({
  id: "dependencies",
  tool: {
    title: "Service dependencies",
    description: "Browse the downstream dependencies of one service. Group key is `coalesce(attributes.peer.service, attributes.net.peer.name, attributes.db.system, attributes.messaging.system)`. Returns per-dependency call count, error count, error rate, and latency percentiles. Pass `dataSourceId` (from `list_data_sources`) and `serviceName`; optional `dataset` (the span index pattern \u2014 discover via `list_index_patterns`, defaults to `otel-v1-apm-span-*`) and `limit` (default 100).",
    inputSchema: inputSchema178
  },
  propsSchema: propsSchema178,
  view: DependenciesView,
  handler: async ({ dataSourceId, dataset, serviceName, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET20;
    const lim = limit ?? DEFAULT_LIMIT26;
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | eval dependency = coalesce(\`attributes.peer.service\`, \`attributes.net.peer.name\`, \`attributes.db.system\`, \`attributes.messaging.system\`) | where dependency != "" | eval isErr = if(statusCode = 2, 1, 0) | stats count() as callCount, sum(isErr) as errorCount, avg(durationInNanos) as avgDur, percentile(durationInNanos, 50) as p50, percentile(durationInNanos, 95) as p95, percentile(durationInNanos, 99) as p99 by dependency | sort - callCount | head ${lim}`;
    ctx.logger.log("[services.dependencies] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      serviceName
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result).map((r8) => {
        const callCount = r8.getNumber("callCount");
        const errorCount = r8.getNumber("errorCount");
        return {
          dependency: r8.getString("dependency"),
          callCount,
          errorCount,
          errorRate: callCount > 0 ? errorCount / callCount : 0,
          avgLatencyMs: r8.getNumber("avgDur") / NANOS_PER_MS7,
          p50LatencyMs: r8.getNumber("p50") / NANOS_PER_MS7,
          p95LatencyMs: r8.getNumber("p95") / NANOS_PER_MS7,
          p99LatencyMs: r8.getNumber("p99") / NANOS_PER_MS7
        };
      });
      const props = { ...baseProps, rows };
      return {
        props,
        text: rows.length === 0 ? `No dependencies found for ${serviceName}.` : `Loaded ${rows.length} dependency row(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[services.dependencies] PPL failed: " + msg);
      const props = { ...baseProps, rows: [], error: msg };
      return { props, text: "Failed to load dependencies: " + msg, isError: true };
    }
  }
});

