// src/apps/services/kpi-cards/tool.ts
var DEFAULT_DATASET21 = "otel-v1-apm-span-*";
var NANOS_PER_MS8 = 1e6;
var kpiCardsRoute = defineRoute({
  id: "kpi-cards",
  tool: {
    title: "Service KPI cards",
    description: "Render the 5 service KPI cards (throughput, fault rate, error rate, availability, p99 latency) for one service from a trace span index. Pass `dataSourceId` (from `list_data_sources`) and `serviceName`; optional `dataset` (the span index pattern title \u2014 discover via `list_index_patterns`, defaults to `otel-v1-apm-span-*`).",
    inputSchema: inputSchema179
  },
  propsSchema: propsSchema179,
  view: KpiCardsView,
  handler: async ({ dataSourceId, dataset, serviceName }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET21;
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | eval isErr = if(statusCode = 2, 1, 0) | eval isFault = if(statusCode >= 2, 1, 0) | stats count() as throughput, sum(isErr) as errors, sum(isFault) as faults, percentile(durationInNanos, 99) as p99`;
    ctx.logger.log("[services.kpi-cards] PPL: " + query);
    const baseProps = { dataset: ds, query, serviceName };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const rows = pplRows(result);
      const row = rows[0];
      const throughput = row?.getNumber("throughput") ?? 0;
      const errors = row?.getNumber("errors") ?? 0;
      const faults = row?.getNumber("faults") ?? 0;
      const p99Nanos = row?.getNumber("p99") ?? 0;
      const errorRate = throughput > 0 ? errors / throughput : 0;
      const faultRate = throughput > 0 ? faults / throughput : 0;
      const availability = throughput > 0 ? 1 - errorRate : 1;
      const props = {
        ...baseProps,
        throughput,
        faultRate,
        errorRate,
        availability,
        p99LatencyMs: p99Nanos / NANOS_PER_MS8
      };
      return {
        props,
        text: throughput === 0 ? `No spans found for ${serviceName} in ${ds}.` : `Loaded KPIs for ${serviceName} from ${ds}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[services.kpi-cards] PPL failed: " + msg);
      const props = {
        ...baseProps,
        throughput: 0,
        faultRate: 0,
        errorRate: 0,
        availability: 0,
        p99LatencyMs: 0,
        error: msg
      };
      return { props, text: "Failed to load KPIs: " + msg, isError: true };
    }
  }
});

