// src/apps/services/operations/tool.ts
var DEFAULT_DATASET23 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT27 = 100;
var NANOS_PER_MS10 = 1e6;
var operationsRoute = defineRoute({
  id: "operations",
  tool: {
    title: "Service operations",
    description: "Browse the operations of one service with per-operation request count, error count, error rate, avg/p50/p95/p99 latency. Pass `dataSourceId` (from `list_data_sources`) and `serviceName`; optional `dataset` (the span index pattern \u2014 discover via `list_index_patterns`, defaults to `otel-v1-apm-span-*`), `filter` (`minLatencyMs`, `maxErrorRate`, `search`), and `limit` (default 100).",
    inputSchema: inputSchema181
  },
  propsSchema: propsSchema181,
  view: OperationsView,
  handler: async ({ dataSourceId, dataset, serviceName, filter, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET23;
    const lim = limit ?? DEFAULT_LIMIT27;
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | eval isErr = if(statusCode = 2, 1, 0) | stats count() as callCount, sum(isErr) as errorCount, avg(durationInNanos) as avgDur, percentile(durationInNanos, 50) as p50, percentile(durationInNanos, 95) as p95, percentile(durationInNanos, 99) as p99 by name | sort - callCount | head ${lim}`;
    ctx.logger.log("[services.operations] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      serviceName,
      filter
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const search = filter?.search?.toLowerCase().trim();
      const minLatencyMs = filter?.minLatencyMs;
      const maxErrorRate = filter?.maxErrorRate;
      const rows = [];
      for (const r8 of pplRows(result)) {
        const operation2 = r8.getString("name");
        if (!operation2) continue;
        if (search && !operation2.toLowerCase().includes(search)) continue;
        const callCount = r8.getNumber("callCount");
        const errorCount = r8.getNumber("errorCount");
        const errorRate = callCount > 0 ? errorCount / callCount : 0;
        const avgLatencyMs = r8.getNumber("avgDur") / NANOS_PER_MS10;
        if (minLatencyMs !== void 0 && avgLatencyMs < minLatencyMs) continue;
        if (maxErrorRate !== void 0 && errorRate > maxErrorRate) continue;
        rows.push({
          operation: operation2,
          callCount,
          errorCount,
          errorRate,
          avgLatencyMs,
          p50LatencyMs: r8.getNumber("p50") / NANOS_PER_MS10,
          p95LatencyMs: r8.getNumber("p95") / NANOS_PER_MS10,
          p99LatencyMs: r8.getNumber("p99") / NANOS_PER_MS10
        });
      }
      const props = { ...baseProps, rows };
      return {
        props,
        text: rows.length === 0 ? `No operations found for ${serviceName}.` : `Loaded ${rows.length} operation(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[services.operations] PPL failed: " + msg);
      const props = { ...baseProps, rows: [], error: msg };
      return { props, text: "Failed to load operations: " + msg, isError: true };
    }
  }
});

