var DEFAULT_DATASET26 = "otel-v2-apm-service-map";
var DEFAULT_LIMIT29 = 20;
var topDepPathsRoute = defineRoute({
  id: "top-dep-paths",
  tool: {
    title: "Top dependency paths by fault rate",
    description: "Top-K (caller, callee) edges in the service map by fault rate (errorCount / requestCount). Pass `dataSourceId` (from `list_data_sources`); optional `dataset` (default `otel-v2-apm-service-map` \u2014 discover via `list_index_patterns`) and `limit` (default 20).",
    inputSchema: inputSchema184
  },
  propsSchema: propsSchema184,
  view: TopDepPathsView,
  handler: async ({ dataSourceId, dataset, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET26;
    const lim = limit ?? DEFAULT_LIMIT29;
    const query = `source = ${ds} | where serviceName != "" and \`destination.resource\` != "" | head 5000`;
    ctx.logger.log("[services.top-dep-paths] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      limit: lim
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const agg = /* @__PURE__ */ new Map();
      for (const row of pplRows(result)) {
        const caller = row.getString("serviceName");
        const callee = row.getString("destination.resource") || row.getString("target");
        if (!caller || !callee) continue;
        const status = row.getNumber("statusCode") || row.getNumber("status_code");
        const err = status === 2 ? 1 : 0;
        const key = `${caller}	${callee}`;
        const cur = agg.get(key) ?? { caller, callee, requests: 0, errors: 0 };
        cur.requests += 1;
        cur.errors += err;
        agg.set(key, cur);
      }
      const edges = Array.from(agg.values()).map((v3) => ({
        caller: v3.caller,
        callee: v3.callee,
        requestCount: v3.requests,
        errorCount: v3.errors,
        faultRate: v3.requests > 0 ? v3.errors / v3.requests : 0
      })).sort((a7, b7) => {
        if (b7.faultRate !== a7.faultRate) return b7.faultRate - a7.faultRate;
        return b7.requestCount - a7.requestCount;
      }).slice(0, lim);
      const props = { ...baseProps, edges };
      return {
        props,
        text: edges.length === 0 ? `No dependency edges found in ${ds}.` : `Loaded top ${edges.length} dependency path(s) by fault rate.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[services.top-dep-paths] PPL failed: " + msg);
      const props = { ...baseProps, edges: [], error: msg };
      return {
        props,
        text: "Failed to load top dependency paths: " + msg,
        isError: true
      };
    }
  }
});

