// src/apps/sizing-calculator/compute/tool.ts
var GB = 1024 ** 3;
var computeRoute2 = defineRoute({
  id: "compute",
  tool: {
    title: "Estimate trace storage",
    description: "Compute trace storage estimates from traces-per-day, avg spans-per-trace, and avg span byte size. Returns daily span / RED metrics / service map volume and 30-day total.",
    inputSchema: inputSchema186
  },
  propsSchema: propsSchema186,
  view: ComputeView2,
  handler: async ({ tracesPerDay, avgSpansPerTrace, avgSpanBytes }) => {
    const spans = avgSpansPerTrace ?? 10;
    const bytes = avgSpanBytes ?? 1024;
    const spanStorageBytesPerDay = tracesPerDay * spans * bytes;
    const spanStorageGbPerDay = spanStorageBytesPerDay / GB;
    const redMetricsGbPerDay = spanStorageGbPerDay * 0.01;
    const serviceMapGbPerDay = spanStorageGbPerDay * 5e-3;
    const totalGbPerMonth = (spanStorageGbPerDay + redMetricsGbPerDay + serviceMapGbPerDay) * 30;
    const props = {
      tracesPerDay,
      avgSpansPerTrace: spans,
      avgSpanBytes: bytes,
      spanStorageGbPerDay,
      redMetricsGbPerDay,
      serviceMapGbPerDay,
      totalGbPerMonth
    };
    return {
      props,
      text: `Estimated ${totalGbPerMonth.toFixed(2)} GB / month total.`
    };
  }
});

