// src/apps/slos/active-alerts/tool.ts
var DATASET15 = ".opensearch-alerting-alerts";
var activeAlertsRoute = defineRoute({
  id: "active-alerts",
  tool: {
    title: "Active SLO alerts",
    description: "Inspect currently firing alerts from the live alerting index. Pass `dataSourceId` (from `list_data_sources`). Reads `.opensearch-alerting-alerts` via PPL.",
    inputSchema: inputSchema187
  },
  propsSchema: propsSchema187,
  view: ActiveAlertsView,
  handler: async ({ dataSourceId }, ctx) => {
    const query = `source = ${DATASET15} | where state = "ACTIVE" | sort - start_time | head 100`;
    ctx.logger.log("[slos.active-alerts] PPL: " + query);
    const baseProps = {
      dataset: DATASET15,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, DATASET15);
      const alerts = pplRows(result).map((row, i7) => ({
        id: row.getString("alert_id") || row.getString("id") || `row-${i7}`,
        monitorName: row.getString("monitor_name"),
        severity: row.getString("severity"),
        state: row.getString("state"),
        startTime: row.getString("start_time"),
        message: row.getString("alert_info") || row.getString("message"),
        triggerName: row.getString("trigger_name")
      }));
      const props = { ...baseProps, alerts };
      return {
        props,
        text: alerts.length === 0 ? "No active alerts." : `${alerts.length} active alert(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[slos.active-alerts] PPL failed: " + msg);
      const props = { ...baseProps, alerts: [], error: msg };
      return {
        props,
        text: "Failed to load active alerts: " + msg,
        isError: true
      };
    }
  }
});

