// src/apps/slos/alerting-rules/tool.ts
var alertingRulesRoute = defineRoute({
  id: "alerting-rules",
  tool: {
    title: "SLO alerting rules",
    description: "Inspect alerting rules: lists OpenSearch alerting monitors and (when available) Cortex / Prometheus rules. Pass `dataSourceId` (from `list_data_sources`).",
    inputSchema: inputSchema188
  },
  propsSchema: propsSchema188,
  view: AlertingRulesView,
  handler: async ({ dataSourceId }, ctx) => {
    const rules = [];
    let lastError = null;
    try {
      const monitors = await ctx.osUi.findSavedObjects("monitor", {
        dataSourceId
      });
      for (const m5 of monitors) {
        rules.push({
          id: m5.id,
          name: m5.title || m5.id,
          description: m5.description || "",
          source: "monitor"
        });
      }
    } catch (err) {
      lastError = err;
      ctx.logger.warn(
        "[slos.alerting-rules] monitor lookup failed: " + errorMessage(err)
      );
    }
    if (rules.length === 0 && lastError) {
      const msg = errorMessage(lastError);
      const props2 = { dataSourceId, rules: [], error: msg };
      return {
        props: props2,
        text: "Failed to load alerting rules: " + msg,
        isError: true
      };
    }
    const props = { dataSourceId, rules };
    return {
      props,
      text: rules.length === 0 ? "No alerting rules found." : `Loaded ${rules.length} rule(s).`
    };
  }
});

