// src/apps/slos/budget-timeseries/tool.ts
var TYPES4 = ["observability-slo", "slo"];
var DEFAULT_INTERVAL3 = 60;
function parseTarget(raw) {
  const trimmed = raw.trim();
  if (!trimmed) return { value: 0.999, label: "" };
  let n3 = parseFloat(trimmed.replace(/%$/, ""));
  if (!isFinite(n3)) return { value: 0.999, label: trimmed };
  if (n3 > 1) n3 = n3 / 100;
  return { value: n3, label: trimmed };
}
var budgetTimeseriesRoute = defineRoute({
  id: "budget-timeseries",
  tool: {
    title: "SLO error-budget timeseries",
    description: "Plot remaining error budget over time. Aggregates errors per bucket and subtracts from the configured budget. Pass `dataSourceId` (from `list_data_sources`) and `sloId` (from `slos_list`); optional `intervalMinutes` (default 60).",
    inputSchema: inputSchema190
  },
  propsSchema: propsSchema190,
  view: BudgetTimeseriesView,
  handler: async ({ dataSourceId, sloId, intervalMinutes }, ctx) => {
    const interval = intervalMinutes ?? DEFAULT_INTERVAL3;
    let target = 0.999;
    let targetLabel = "99.9%";
    let title = sloId;
    let sourceIndex = "";
    let filterField = "slo_id";
    for (const type of TYPES4) {
      try {
        const objects = await ctx.osUi.findSavedObjects(type, {
          dataSourceId,
          search: sloId
        });
        const match = objects.find((o3) => o3.id === sloId) ?? objects[0];
        if (!match) continue;
        title = match.title || sloId;
        const t2 = parseTarget(asString4(match.attributes.target));
        target = t2.value;
        targetLabel = t2.label || `${(t2.value * 100).toFixed(2)}%`;
        sourceIndex = asString4(match.attributes.indicator) || asString4(match.attributes.index) || "";
        filterField = asString4(match.attributes.filter_field) || "slo_id";
        break;
      } catch (err) {
        ctx.logger.warn(
          `[slos.budget-timeseries] type=${type} failed: ${errorMessage(err)}`
        );
      }
    }
    const safeId = sloId.replace(/"/g, '\\"');
    const dataset = sourceIndex || ".plugins-slo-results-*";
    const query = `source = ${dataset} | where ${filterField} = "${safeId}" | stats sum(errors) as errors, sum(total) as total by span(@timestamp, ${interval}m) as bucket | sort + bucket | head 200`;
    ctx.logger.log("[slos.budget-timeseries] PPL: " + query);
    const budgetTotal = 1 - target;
    const baseProps = {
      dataSourceId,
      sloId,
      title,
      target,
      targetLabel,
      intervalMinutes: interval,
      budgetTotal,
      query
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, dataset);
      const buckets = pplRows(result).map((row) => {
        const errors = toNumber(row.get("errors"));
        const total = toNumber(row.get("total"));
        const failureRatio = total > 0 ? errors / total : 0;
        const remaining = Math.max(0, budgetTotal - failureRatio);
        return {
          bucket: row.getString("bucket"),
          errors,
          remaining
        };
      });
      const props = { ...baseProps, buckets };
      return {
        props,
        text: buckets.length === 0 ? "No SLO result data in range." : `Loaded ${buckets.length} bucket(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[slos.budget-timeseries] PPL failed: " + msg);
      const props = {
        ...baseProps,
        buckets: [],
        error: msg
      };
      return {
        props,
        text: "Failed to load budget timeseries: " + msg,
        isError: true
      };
    }
  }
});

