var PORTS = [
  { name: "OpenSearch", port: 9200 },
  { name: "OTel HTTP", port: 4318 },
  { name: "OTel gRPC", port: 4317 },
  { name: "Data Prepper", port: 21890 },
  { name: "Prometheus", port: 9090 },
  { name: "OSD", port: 5601 }
];
var COMPONENTS = [
  { name: "OpenSearch", status: "unknown", note: "Connect a data source to verify." },
  { name: "OpenSearch Dashboards", status: "ok" },
  { name: "OTel Collector", status: "unknown" },
  { name: "Data Prepper", status: "unknown" },
  { name: "Prometheus / Cortex", status: "unknown" }
];
var checkRoute = defineRoute({
  id: "check",
  tool: {
    title: "Stack health check",
    description: "Stack health summary. Returns the canonical port reference and component placeholders. If `dataSourceId` is supplied, also lists indices via `_cat/indices`.",
    inputSchema: inputSchema205
  },
  propsSchema: propsSchema205,
  view: CheckView,
  handler: async ({ dataSourceId }, ctx) => {
    if (!dataSourceId) {
      const props = {
        indices: [],
        components: COMPONENTS,
        ports: PORTS
      };
      return {
        props,
        text: "Showing static stack-health reference. Pass dataSourceId to list indices."
      };
    }
    try {
      const indices = await ctx.osUi.catIndices(dataSourceId);
      const props = {
        dataSourceId,
        indices,
        components: COMPONENTS.map(
          (c7) => c7.name === "OpenSearch" ? { ...c7, status: "ok", note: `Reached cluster (${indices.length} indices).` } : c7
        ),
        ports: PORTS
      };
      return { props, text: `Listed ${indices.length} indices on ${dataSourceId}.` };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[stack-health.check] catIndices failed: " + msg);
      const props = {
        dataSourceId,
        indices: [],
        components: COMPONENTS.map(
          (c7) => c7.name === "OpenSearch" ? { ...c7, status: "error", note: msg } : c7
        ),
        ports: PORTS,
        error: msg
      };
      return {
        props,
        text: "Failed to list indices (data source may not be OpenSearch): " + msg,
        isError: true
      };
    }
  }
});

