// src/apps/stack-health/doc-counts/tool.ts
var DEFAULTS = {
  traces: "otel-v1-apm-span-*",
  serviceMap: "otel-v2-apm-service-map",
  logs: "logs-otel-v1-*"
};
async function runCount(ctx, dataSourceId, target) {
  const query = `source = ${target.dataset} | stats count() as count`;
  ctx.logger.log(`[stack-health.doc-counts] PPL: ${query}`);
  try {
    const result = await ctx.osUi.runPpl(
      dataSourceId,
      query,
      target.dataset
    );
    const rows = pplRows(result);
    const count2 = rows.length > 0 ? rows[0].getNumber("count") : 0;
    return {
      label: target.label,
      dataset: target.dataset,
      count: count2,
      status: count2 > 0 ? "green" : "gray",
      query
    };
  } catch (err) {
    const msg = errorMessage(err);
    ctx.logger.error(
      `[stack-health.doc-counts] count failed for ${target.dataset}: ${msg}`
    );
    return {
      label: target.label,
      dataset: target.dataset,
      count: 0,
      status: "red",
      query,
      error: msg
    };
  }
}
var docCountsRoute = defineRoute({
  id: "doc-counts",
  tool: {
    title: "Stack health: doc counts",
    description: "Confirm trace, service-map, and log documents are landing. Runs `source = <ds> | stats count()` against the three canonical index patterns in parallel and renders a KPI card per signal. Pass `dataSourceId` (from `list_data_sources`); optional `tracesDataset` (default `otel-v1-apm-span-*`), `serviceMapDataset` (default `otel-v2-apm-service-map`), and `logsDataset` (default `logs-otel-v1-*`).",
    inputSchema: inputSchema206
  },
  propsSchema: propsSchema206,
  view: DocCountsView,
  handler: async ({ dataSourceId, tracesDataset, logsDataset, serviceMapDataset }, ctx) => {
    const targets = [
      { label: "Traces", dataset: tracesDataset?.trim() || DEFAULTS.traces },
      {
        label: "Service map",
        dataset: serviceMapDataset?.trim() || DEFAULTS.serviceMap
      },
      { label: "Logs", dataset: logsDataset?.trim() || DEFAULTS.logs }
    ];
    const cards = await Promise.all(
      targets.map((t2) => runCount(ctx, dataSourceId, t2))
    );
    const errors = cards.filter((c7) => c7.status === "red").length;
    const greens = cards.filter((c7) => c7.status === "green").length;
    const props = { cards };
    const summary3 = `Doc-counts: ${greens}/${cards.length} signals landing` + (errors > 0 ? `, ${errors} errored.` : ".");
    return { props, text: summary3, isError: errors > 0 && greens === 0 };
  }
});

