var SERVICES = [
  {
    name: "OpenSearch",
    composeService: "opensearch",
    description: "Cluster node. Tail when queries fail or indices are missing.",
    command: "docker compose logs --tail=200 opensearch"
  },
  {
    name: "OpenSearch Dashboards",
    composeService: "dashboards",
    description: "OSD UI server. Tail when the UI fails to render or auth flows break.",
    command: "docker compose logs --tail=200 dashboards"
  },
  {
    name: "OTel Collector",
    composeService: "otel-collector",
    description: "Telemetry receiver. Tail when traces/logs aren't reaching Data Prepper or remote_write fails.",
    command: "docker compose logs --tail=200 otel-collector"
  },
  {
    name: "Data Prepper",
    composeService: "data-prepper",
    description: "Trace + log pipelines. Tail when otel-v1-apm-span-* / otel-v2-apm-service-map / logs-otel-v1-* aren't being written.",
    command: "docker compose logs --tail=200 data-prepper"
  },
  {
    name: "Prometheus",
    composeService: "prometheus",
    description: "Metrics store. Tail when scrape targets are down or remote_write rejects samples.",
    command: "docker compose logs --tail=200 prometheus"
  }
];
var NOTES11 = [
  "Run from the directory that has docker-compose.yml. The compose project name defaults to the directory name.",
  "Add `--since 10m` to limit to the last 10 minutes when chasing a recent incident.",
  "If you renamed services in your compose file, swap the second token; the flags are unchanged.",
  "When containers run on a remote host, prefix with `DOCKER_HOST=ssh://host` or use `kubectl logs <pod>` for k8s deployments."
];
var serviceLogsRoute = defineRoute({
  id: "service-logs",
  tool: {
    title: "Tail one component's logs",
    description: "Reference panel: docker-compose log-tail commands for each stack component (OpenSearch / OSD / OTel Collector / Data Prepper / Prometheus). Use to read what failed when a component is unhealthy.",
    inputSchema: inputSchema208
  },
  propsSchema: propsSchema208,
  view: ServiceLogsView,
  handler: async () => {
    const props = {
      services: SERVICES,
      followCommand: "docker compose logs -f --tail=50 <service>",
      notes: NOTES11
    };
    return {
      props,
      text: `Service-logs reference: ${SERVICES.length} components.`
    };
  }
});

