var OTEL_COLLECTOR_YAML = `# otel-collector.yaml
receivers:
  otlp:
    protocols:
      grpc:
        endpoint: 0.0.0.0:4317
      http:
        endpoint: 0.0.0.0:4318

processors:
  batch:
    timeout: 5s
    send_batch_size: 1024
  memory_limiter:
    check_interval: 1s
    limit_percentage: 80
    spike_limit_percentage: 25
  resource:
    attributes:
      - key: deployment.environment
        value: \${env:OTEL_ENV}
        action: upsert

exporters:
  otlphttp/data-prepper:
    endpoint: http://data-prepper:21890
    tls:
      insecure: true
  prometheusremotewrite:
    endpoint: http://prometheus:9090/api/v1/write

service:
  pipelines:
    traces:
      receivers: [otlp]
      processors: [memory_limiter, batch, resource]
      exporters: [otlphttp/data-prepper]
    logs:
      receivers: [otlp]
      processors: [memory_limiter, batch, resource]
      exporters: [otlphttp/data-prepper]
    metrics:
      receivers: [otlp]
      processors: [memory_limiter, batch]
      exporters: [prometheusremotewrite]
`;
var SECTIONS16 = [
  {
    name: "Receivers",
    description: "Where the Collector listens. OTLP is the canonical OpenTelemetry wire format.",
    items: [
      "otlp / grpc on :4317",
      "otlp / http on :4318"
    ]
  },
  {
    name: "Processors",
    description: "Per-batch pipeline stages applied before export. Order matters \u2014 memory_limiter first, then batch, then resource enrichment.",
    items: [
      "memory_limiter \u2014 back-pressure when heap is hot",
      "batch \u2014 coalesce signals to reduce export RPCs",
      "resource \u2014 stamp resource attributes (env, region, version)"
    ]
  },
  {
    name: "Exporters",
    description: "Where signals leave. Traces and logs go to Data Prepper; metrics go to Prometheus / Cortex via remote_write.",
    items: [
      "otlphttp/data-prepper \u2014 :21890",
      "prometheusremotewrite \u2014 :9090/api/v1/write"
    ]
  }
];
var otelYamlRoute = defineRoute({
  id: "otel-yaml",
  tool: {
    title: "OTel Collector pipeline YAML",
    description: "Reference panel: example OpenTelemetry Collector config with receivers, processors, and exporters wired for traces / logs / metrics.",
    inputSchema: inputSchema214
  },
  propsSchema: propsSchema214,
  view: OtelYamlView,
  handler: async () => {
    const props = {
      yaml: OTEL_COLLECTOR_YAML,
      sections: SECTIONS16
    };
    return { props, text: "OTel Collector pipeline reference." };
  }
});

