// src/apps/topology-map/filter-error/tool.ts
var DEFAULT_DATASET32 = "otel-v2-apm-service-map";
var filterErrorRoute = defineRoute({
  id: "filter-error",
  tool: {
    title: "Map nodes by error rate",
    description: "Filter service-map destination nodes by error rate bucket: `lt1` (<1%), `1to5` (1%\u20135%), `gt5` (>5%). Pass `dataSourceId` (from `list_data_sources`), `bucket`, and optional `dataset` (default `otel-v2-apm-service-map`).",
    inputSchema: inputSchema222
  },
  propsSchema: propsSchema222,
  view: FilterErrorView,
  handler: async ({ dataSourceId, dataset, bucket }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET32;
    const safeDs = ds.replace(/"/g, '\\"');
    const query = `source = ${safeDs} | head 5000`;
    ctx.logger.log("[topology-map.filter-error] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      bucket
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const agg = /* @__PURE__ */ new Map();
      for (const row of pplRows(result)) {
        const target = row.getString("destination.resource") || row.getString("target");
        const source = row.getString("serviceName");
        const node = target || source;
        const kind = row.getString("kind");
        if (!node) continue;
        if (target && kind && kind.toUpperCase().includes("SERVER")) continue;
        const status = row.getNumber("status_code");
        const err = status >= 2 ? 1 : 0;
        const cur = agg.get(node) ?? { calls: 0, errors: 0 };
        cur.calls += 1;
        cur.errors += err;
        agg.set(node, cur);
      }
      const all = Array.from(agg, ([name, v3]) => ({
        name,
        callCount: v3.calls,
        errorCount: v3.errors,
        errorRate: v3.calls > 0 ? v3.errors / v3.calls : 0
      }));
      const filtered = all.filter((n3) => {
        if (bucket === "lt1") return n3.errorRate < 0.01;
        if (bucket === "1to5") return n3.errorRate >= 0.01 && n3.errorRate <= 0.05;
        return n3.errorRate > 0.05;
      });
      filtered.sort((a7, b7) => b7.errorRate - a7.errorRate);
      const props = { ...baseProps, nodes: filtered };
      return {
        props,
        text: filtered.length === 0 ? `No nodes in error bucket ${bucket}.` : `Loaded ${filtered.length} node(s) in error bucket ${bucket}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[topology-map.filter-error] PPL failed: " + msg);
      const props = { ...baseProps, nodes: [], error: msg };
      return { props, text: "Failed to load: " + msg, isError: true };
    }
  }
});

