var DEFAULT_DATASET34 = "otel-v2-apm-service-map";
var groupCardsRoute = defineRoute({
  id: "group-cards",
  tool: {
    title: "Topology grouped as cards",
    description: "Group the service-map by an attribute (e.g. `attributes.deployment.environment`, `resource.team`) and render a card grid where each card shows the group label and service count. Pass `dataSourceId` (from `list_data_sources`), `groupBy`, and optional `dataset` (default `otel-v2-apm-service-map`).",
    inputSchema: inputSchema224
  },
  propsSchema: propsSchema224,
  view: GroupCardsView,
  handler: async ({ dataSourceId, dataset, groupBy: groupBy2 }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET34;
    const safeGroup = groupBy2.replace(/`/g, "");
    const query = `source = ${ds} | stats count() as count by \`${safeGroup}\` | sort - count`;
    ctx.logger.log("[topology-map.group-cards] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      groupBy: groupBy2
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const cards = pplRows(result).map((r8) => ({
        group: r8.getString(safeGroup) || "(unset)",
        count: r8.getNumber("count")
      }));
      const props = { ...baseProps, cards };
      return {
        props,
        text: cards.length === 0 ? `No groups for ${groupBy2}.` : `Loaded ${cards.length} group(s).`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[topology-map.group-cards] PPL failed: " + msg);
      const props = { ...baseProps, cards: [], error: msg };
      return { props, text: "Failed to load: " + msg, isError: true };
    }
  }
});

