// src/apps/topology-map/node-detail/tool.ts
var DEFAULT_DATASET35 = "otel-v1-apm-span-*";
var NANOS_PER_MS11 = 1e6;
var nodeDetailRoute = defineRoute({
  id: "node-detail",
  tool: {
    title: "Topology node detail",
    description: "Side-detail panel for one service node on the topology map. Aggregates the span index for that service into requests, errors, faults, and p50/p90/p99 latency. Pass `dataSourceId` (from `list_data_sources`) and `serviceName`; optional `dataset` (default `otel-v1-apm-span-*` \u2014 discover via `list_index_patterns`).",
    inputSchema: inputSchema225
  },
  propsSchema: propsSchema225,
  view: NodeDetailView,
  handler: async ({ dataSourceId, dataset, serviceName }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET35;
    const safeSvc = serviceName.replace(/"/g, '\\"');
    const query = `source = ${ds} | where serviceName = "${safeSvc}" | eval isErr = if(statusCode = 2, 1, 0) | eval isFault = if(statusCode >= 2, 1, 0) | stats count() as requests, sum(isErr) as errors, sum(isFault) as faults, percentile(durationInNanos, 50) as p50, percentile(durationInNanos, 90) as p90, percentile(durationInNanos, 99) as p99`;
    ctx.logger.log("[topology-map.node-detail] PPL: " + query);
    const baseProps = { dataset: ds, query, serviceName };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const row = pplRows(result)[0];
      const requests = row?.getNumber("requests") ?? 0;
      const errors = row?.getNumber("errors") ?? 0;
      const faults = row?.getNumber("faults") ?? 0;
      const props = {
        ...baseProps,
        requests,
        errors,
        faults,
        errorRate: requests > 0 ? errors / requests : 0,
        faultRate: requests > 0 ? faults / requests : 0,
        p50LatencyMs: (row?.getNumber("p50") ?? 0) / NANOS_PER_MS11,
        p90LatencyMs: (row?.getNumber("p90") ?? 0) / NANOS_PER_MS11,
        p99LatencyMs: (row?.getNumber("p99") ?? 0) / NANOS_PER_MS11
      };
      return {
        props,
        text: requests === 0 ? `No spans found for ${serviceName}.` : `Loaded node detail for ${serviceName}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[topology-map.node-detail] PPL failed: " + msg);
      const props = {
        ...baseProps,
        requests: 0,
        errors: 0,
        faults: 0,
        errorRate: 0,
        faultRate: 0,
        p50LatencyMs: 0,
        p90LatencyMs: 0,
        p99LatencyMs: 0,
        error: msg
      };
      return { props, text: "Failed to load: " + msg, isError: true };
    }
  }
});

