var DEFAULT_DATASET38 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT33 = 20;
var NANOS_PER_MS12 = 1e6;
var topGroupsRoute = defineRoute({
  id: "top-groups",
  tool: {
    title: "Top groups leaderboard",
    description: "Rank arbitrary group-by attributes (e.g. `resource.environment`, `attributes.app.version`, `serviceName`) by trace count and p99 latency. Pass `dataSourceId` and `groupBy`. Optional `dataset` (default `otel-v1-apm-span-*`) and `limit` (default 20).",
    inputSchema: inputSchema228
  },
  propsSchema: propsSchema228,
  view: TopGroupsView,
  handler: async ({ dataSourceId, dataset, groupBy: groupBy2, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET38;
    const lim = limit ?? DEFAULT_LIMIT33;
    const field = groupBy2.trim();
    const query = `source = ${ds} | stats count() as traces, percentile(durationInNanos, 99) as p99 by ${field} | sort - traces | head ${lim}`;
    ctx.logger.log("[trace-dashboard.top-groups] PPL: " + query);
    const baseProps = {
      dataset: ds,
      query,
      groupBy: field
    };
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const groups = pplRows(result).map((r8) => ({
        group: r8.getString(field) || r8.getString(field.split(".").pop() || ""),
        traces: r8.getNumber("traces"),
        p99Ms: r8.getNumber("p99") / NANOS_PER_MS12
      }));
      const props = { ...baseProps, groups };
      return {
        props,
        text: groups.length === 0 ? `No groups found for ${field} in ${ds}.` : `Loaded ${groups.length} group(s) by ${field} in ${ds}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[trace-dashboard.top-groups] PPL failed: " + msg);
      return {
        props: { ...baseProps, groups: [], error: msg },
        text: "Failed to load top groups: " + msg,
        isError: true
      };
    }
  }
});

