var DEFAULT_DATASET42 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT37 = 500;
var detailsRoute = defineRoute({
  id: "details",
  tool: {
    title: "Trace details",
    description: "Load all spans for a single OpenTelemetry trace and render them as a hierarchy with inline timeline bars and a span attribute panel. Pass `dataSourceId` (from `list_data_sources`), `dataset` (the trace index pattern title \u2014 discover via `list_index_patterns`, e.g. `otel-v1-apm-span-*`), and `traceId`; optionally override `limit` (default 500).",
    inputSchema: inputSchema234
  },
  propsSchema: propsSchema234,
  view: DetailsView,
  handler: async ({ dataSourceId, traceId, dataset, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET42;
    const lim = limit ?? DEFAULT_LIMIT37;
    const baseProps = {
      traceId,
      dataset: ds
    };
    const safeId = traceId.replace(/"/g, '\\"');
    const query = `source = ${ds} | where traceId = "${safeId}" | head ${lim}`;
    ctx.logger.log("[traces.details] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const { spans, rangeStartNanos, rangeEndNanos } = transformPplToSpans(
        result,
        traceId
      );
      const props = {
        ...baseProps,
        spans,
        rangeStartNanos,
        rangeEndNanos
      };
      return {
        props,
        text: spans.length === 0 ? `No spans found for traceId=${traceId} in ${ds}.` : `Loaded ${spans.length} span(s) for traceId=${traceId}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[traces.details] PPL failed: " + msg);
      const props = {
        ...baseProps,
        spans: [],
        rangeStartNanos: 0,
        rangeEndNanos: 0,
        error: msg
      };
      return { props, text: "Failed to load spans: " + msg, isError: true };
    }
  }
});

