var DEFAULT_DATASET45 = "otel-v1-apm-span-*";
var DEFAULT_LIMIT40 = 500;
var ganttRoute2 = defineRoute({
  id: "gantt",
  tool: {
    title: "Trace Gantt timeline",
    description: "Render a Gantt-style timeline of all spans for a trace, sorted by start time. Each span is a horizontal bar coloured by service. Pass `dataSourceId` (from `list_data_sources`), `traceId`, and optionally `dataset` (defaults to `otel-v1-apm-span-*`) and `limit` (default 500).",
    inputSchema: inputSchema237
  },
  propsSchema: propsSchema237,
  view: GanttView2,
  handler: async ({ dataSourceId, traceId, dataset, limit }, ctx) => {
    const ds = dataset?.trim() || DEFAULT_DATASET45;
    const lim = limit ?? DEFAULT_LIMIT40;
    const baseProps = {
      traceId,
      dataset: ds
    };
    const safeId = traceId.replace(/"/g, '\\"');
    const query = `source = ${ds} | where traceId = "${safeId}" | head ${lim}`;
    ctx.logger.log("[traces.gantt] PPL: " + query);
    try {
      const result = await ctx.osUi.runPpl(dataSourceId, query, ds);
      const { spans, rangeStartNanos, rangeEndNanos } = transformPplToSpans(
        result,
        traceId
      );
      const props = {
        ...baseProps,
        spans,
        rangeStartNanos,
        rangeEndNanos
      };
      return {
        props,
        text: spans.length === 0 ? `No spans found for traceId=${traceId} in ${ds}.` : `Loaded ${spans.length} span(s) for traceId=${traceId}.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[traces.gantt] PPL failed: " + msg);
      const props = {
        ...baseProps,
        spans: [],
        rangeStartNanos: 0,
        rangeEndNanos: 0,
        error: msg
      };
      return { props, text: "Failed to load spans: " + msg, isError: true };
    }
  }
});

