var SECTIONS19 = [
  {
    title: "Goal",
    body: "Selecting a span in the Tree, DAG, or Gantt view should highlight the same span in the other two. The contract is a typed event bus on `window`."
  },
  {
    title: "Bus shape",
    body: "A single CustomEvent named `traces:span-selected` carries `{ spanId, source }`. Each view dispatches on click and listens for events from other sources.",
    code: "interface SpanSelectedDetail { spanId: string; source: 'tree' | 'dag' | 'gantt' | 'compare' }\nwindow.dispatchEvent(new CustomEvent('traces:span-selected', { detail }));"
  },
  {
    title: "Subscribe pattern",
    body: "Each view installs an effect that listens for the event and ignores echoes from itself. Selection state lives in local React state.",
    code: "useEffect(() => {\n  const fn = (e: Event) => {\n    const d = (e as CustomEvent).detail as SpanSelectedDetail;\n    if (d.source === MY_SOURCE) return;\n    setSelected(d.spanId);\n  };\n  window.addEventListener('traces:span-selected', fn);\n  return () => window.removeEventListener('traces:span-selected', fn);\n}, []);"
  },
  {
    title: "Why a CustomEvent and not a context?",
    body: "Each view is a separate MCP App entry / iframe. They don't share React context \u2014 they only share the host window. The CustomEvent bus is the lightest IPC primitive available."
  }
];
