// src/apps/workspaces-admin/detail/tool.ts
var detailRoute5 = defineRoute({
  id: "detail",
  tool: {
    title: "Workspace detail",
    description: "Show a single workspace and its associated data sources. Pass `workspaceId` (from `workspaces-admin_list`); optionally `dataSourceId` to scope which data sources count as associated.",
    inputSchema: inputSchema255
  },
  propsSchema: propsSchema255,
  view: DetailView5,
  handler: async ({ workspaceId, dataSourceId }, ctx) => {
    try {
      const matches = await ctx.osUi.findSavedObjects("workspace", {
        search: workspaceId,
        perPage: 100
      });
      const exact = matches.find((o3) => o3.id === workspaceId) ?? null;
      let workspace = null;
      if (exact) {
        const attrs = exact.attributes ?? {};
        workspace = {
          id: exact.id,
          title: exact.title,
          description: exact.description,
          features: Array.isArray(attrs.features) ? attrs.features : [],
          color: typeof attrs.color === "string" ? attrs.color : void 0
        };
      }
      const allDataSources = await ctx.osUi.listDataSources();
      const associatedDataSources = dataSourceId ? allDataSources.filter((d8) => d8.id === dataSourceId) : allDataSources;
      const props = {
        workspaceId,
        workspace,
        associatedDataSources
      };
      return {
        props,
        text: workspace ? `Loaded workspace ${workspace.title} (${associatedDataSources.length} data source(s)).` : `Workspace ${workspaceId} not found.`
      };
    } catch (err) {
      const msg = errorMessage(err);
      ctx.logger.error("[workspaces-admin.detail] failed: " + msg);
      const props = {
        workspaceId,
        workspace: null,
        associatedDataSources: [],
        error: msg
      };
      return { props, text: "Failed to load workspace: " + msg, isError: true };
    }
  }
});

